    private fun nature(): List<Question> = listOf(
        Question(51651, "Quel animal a le plus grand cœur du monde?", listOf("Baleine bleue", "Girafe", "Éléphant", "Rhinocéros"), 0, "Nature", Difficulty.EASY, explanation = "Le cœur d'une baleine bleue peut peser jusqu'à 600 kilogrammes, soit la taille d'une petite voiture, ce qui en fait le plus grand cœur du règne animal."),
        Question(51652, "Combien de cœurs a une pieuvre?", listOf("1", "2", "3", "5"), 1, "Nature", Difficulty.EASY, explanation = "Les pieuvres ont trois cœurs : deux branchiaux qui pompent le sang vers les branchies et un systémique qui le distribue au reste du corps."),
        Question(51653, "Quel est l'animal le plus profond jamais observé?", listOf("Poisson des abysses", "Calmar géant", "Requin des profondeurs", "Méduse géante"), 2, "Nature", Difficulty.EASY, explanation = "Un requin des profondeurs a été filmé à plus de 2 700 mètres de profondeur, battant le record de l'animal vertébré le plus profond jamais observé."),
        Question(51654, "À quelle profondeur se trouve la Fosse des Mariannes?", listOf("5000m", "7000m", "10000m", "15000m"), 3, "Nature", Difficulty.EASY, explanation = "La Fosse des Mariannes est l'endroit le plus profond des océans, atteignant environ 11 000 mètres, et non 15 000 mètres comme indiqué. Cette profondeur a été mesurée par des sondes modernes."),
        Question(51656, "Combien de mètres mesure l'arbre le plus haut du monde?", listOf("100m", "110m", "120m", "150m"), 1, "Nature", Difficulty.EASY, explanation = "L'Hyperion, un séquoia à feuilles d'if situé en Californie, détient le record avec 115,92 mètres, mais l'estimation commune retient environ 110 mètres."),
        Question(51657, "Quel animal peut survivre le plus longtemps sans manger?", listOf("Ours", "Requin", "Tardigrade", "Baleine"), 2, "Nature", Difficulty.EASY, explanation = "Le tardigrade, aussi appelé ourson d'eau, peut entrer en cryptobiose et survivre des décennies sans nourriture, voire plus, en état de déshydratation extrême."),
        Question(51659, "À quelle vitesse le guépard peut-il courir?", listOf("80 km/h", "100 km/h", "120 km/h", "150 km/h"), 0, "Nature", Difficulty.EASY, explanation = "Le guépard est l'animal terrestre le plus rapide, capable d'atteindre 80 km/h en quelques secondes grâce à sa morphologie adaptée à la course."),
        Question(51660, "Quel est l'animal le plus lent du monde?", listOf("Tortue", "Paresseux", "Limace", "Escargot"), 1, "Nature", Difficulty.EASY, explanation = "Le paresseux est considéré comme l'animal le plus lent au monde, avec une vitesse maximale d'environ 0,27 km/h. Cette lenteur est due à son métabolisme très bas et à son régime alimentaire pauvre en énergie."),
        Question(51662, "Quel insecte peut voler le plus vite?", listOf("Libellule", "Abeille", "Frelon", "Papillon"), 3, "Nature", Difficulty.EASY, explanation = "Le papillon de nuit, notamment le sphinx, peut atteindre des vitesses de vol allant jusqu'à 50 km/h, ce qui en fait l'insecte le plus rapide en vol."),
        Question(51663, "À quelle vitesse la libellule peut-elle voler?", listOf("30 km/h", "50 km/h", "80 km/h", "150 km/h"), 0, "Nature", Difficulty.EASY, explanation = "La libellule est l'un des insectes les plus rapides, atteignant environ 30 km/h en vol grâce à ses deux paires d'ailes indépendantes."),
        Question(51664, "Quel est le plus gros insecte jamais découvert?", listOf("Scarabée Goliath", "Insecte bâton", "Cafard préhistorique", "Sauterelle"), 1, "Nature", Difficulty.EASY, explanation = "Le Phrygane géant (ou insecte-bâton géant) de l'île de Bornéo peut atteindre 56 centimètres de long, ce qui en fait le plus long insecte connu."),
        Question(51665, "Combien de dents a un requin blanc?", listOf("100", "200", "300", "500"), 2, "Nature", Difficulty.EASY, explanation = "Le grand requin blanc possède environ 300 dents disposées en plusieurs rangées, qui se renouvellent continuellement tout au long de sa vie."),
        Question(51666, "Quel animal produit du venin le plus puissant?", listOf("Cobra", "Araignée Sydney", "Poisson-pierre", "Méduse-boîte"), 3, "Nature", Difficulty.EASY, explanation = "Le venin de la méduse-boîte est considéré comme le plus puissant au monde, capable de tuer un humain en quelques minutes."),
        Question(51667, "Combien de nerfs optiques a un cerf?", listOf("1", "2", "3", "4"), 0, "Nature", Difficulty.EASY, explanation = "Le cerf, comme tous les mammifères, possède une paire de nerfs optiques, mais ils sont considérés comme un seul nerf optique par œil, donc au total un nerf optique par œil, soit deux nerfs optiques."),
        Question(51668, "Quel animal peut retenir sa respiration le plus longtemps?", listOf("Baleine", "Phoque", "Castor", "Loutre"), 1, "Nature", Difficulty.EASY, explanation = "Les phoques peuvent retenir leur respiration jusqu'à deux heures grâce à une forte concentration en myoglobine et à un métabolisme adapté à la plongée."),
        Question(51669, "Combien de temps une baleine peut-elle retenir sa respiration?", listOf("30 min", "1h", "2h", "4h"), 2, "Nature", Difficulty.EASY, explanation = "Les baleines à bec de Cuvier détiennent le record de plongée chez les mammifères marins, avec une apnée pouvant atteindre 2 heures. Cette adaptation leur permet de chasser en profondeur."),
        Question(51671, "Combien de kilos pèse l'éléphant le plus lourd jamais observé?", listOf("6000", "8000", "10000", "12000"), 0, "Nature", Difficulty.EASY, explanation = "L'éléphant le plus lourd jamais enregistré pesait environ 6 000 kg, soit six tonnes. Ce record a été observé chez un éléphant d'Afrique mâle."),
        Question(51672, "Quel animal a la meilleure vision?", listOf("Aigle", "Faucon", "Lynx", "Chat"), 1, "Nature", Difficulty.EASY, explanation = "Le faucon possède une acuité visuelle exceptionnelle, jusqu'à 8 fois supérieure à celle de l'homme, lui permettant de repérer ses proies à plus d'un kilomètre de distance."),
        Question(51673, "Combien de fois meilleure est la vision du faucon par rapport à l'homme?", listOf("2x", "5x", "8x", "10x"), 2, "Nature", Difficulty.EASY, explanation = "Le faucon possède une acuité visuelle environ huit fois supérieure à celle de l'homme, grâce à une densité plus élevée de photorécepteurs dans sa rétine."),
        Question(51674, "Quel est le plus grand prédateur marin jamais découvert?", listOf("Requin blanc", "Méga-requin", "Léviathan", "Mégalodon"), 3, "Nature", Difficulty.EASY, explanation = "Le Mégalodon, un requin préhistorique géant, est considéré comme le plus grand prédateur marin ayant existé, avec une taille estimée pouvant atteindre 18 mètres."),
        Question(51675, "À quelle taille pouvait atteindre un mégalodon?", listOf("12m", "15m", "18m", "25m"), 0, "Nature", Difficulty.EASY, explanation = "Le mégalodon, un requin préhistorique, atteignait environ 12 mètres de long, soit la taille d’un bus scolaire, d’après les estimations basées sur ses dents fossilisées."),
        Question(51676, "Quel animal a le plus grand nombre de muscles?", listOf("Éléphant", "Baleine", "Octopus", "Humain"), 1, "Nature", Difficulty.MEDIUM, explanation = "La baleine bleue possède le plus grand nombre de muscles de tous les animaux, avec environ 700 muscles, nécessaires pour propulser son corps massif dans l'eau."),
        Question(51677, "Combien de muscles a un octopus?", listOf("1000", "10000", "100000", "1000000"), 2, "Nature", Difficulty.MEDIUM, explanation = "Un poulpe possède environ 100 000 muscles, ce qui lui permet un contrôle extrêmement fin de ses tentacules, chacun capable de mouvements indépendants et précis."),
        Question(51678, "Quel est le plus gros oiseau jamais découvert?", listOf("Autruche", "Émeu", "Maoa narinui", "Moa"), 3, "Nature", Difficulty.MEDIUM, explanation = "Le moa, un oiseau géant incapable de voler de Nouvelle-Zélande, pouvait atteindre 3,6 mètres de haut et peser jusqu'à 250 kilogrammes. Il a disparu après l'arrivée des humains sur l'île."),
        Question(51679, "Quel oiseau peut voler le plus haut?", listOf("Aigles", "Oies", "Grues", "Vautours"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les aigles peuvent atteindre des altitudes de plus de 7 000 mètres, utilisant les courants thermiques pour planer à très haute hauteur."),
        Question(51680, "À quelle altitude les vautours peuvent-ils voler?", listOf("5000m", "8000m", "11000m", "15000m"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les vautours utilisent les courants thermiques pour s'élever à très haute altitude, jusqu'à 8000 mètres, ce qui leur permet de repérer des carcasses sur de vastes distances."),
        Question(51681, "Quel animal a le plus long cou du monde?", listOf("Girafe", "Émeu", "Autruche", "Cygne"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'autruche, bien qu'incapable de voler, possède le cou le plus long de tous les animaux, pouvant atteindre jusqu'à 1,8 mètre, ce qui lui permet de scruter l'horizon dans la savane africaine."),
        Question(51682, "Combien de mètres mesure le cou d'une girafe?", listOf("1m", "1.5m", "2m", "2.5m"), 3, "Nature", Difficulty.MEDIUM, explanation = "Le cou d'une girafe mesure en moyenne 2,5 mètres, ce qui lui permet d'atteindre les feuilles des arbres les plus hauts. Cette adaptation unique est due à des vertèbres allongées, au nombre de sept comme chez l'humain."),
        Question(51683, "Quel animal peut changer de couleur?", listOf("Serpent", "Caméléon", "Poisson", "Oiseau"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le serpent ne change pas de couleur comme le caméléon ou la pieuvre, mais certaines espèces, comme le serpent des blés, peuvent légèrement modifier leur teinte selon la température ou l'humidité."),
        Question(51684, "En combien de secondes un caméléon change-t-il de couleur?", listOf("1s", "5s", "10s", "30s"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le caméléon ne change pas de couleur instantanément : le processus prend environ 5 secondes, car il nécessite une redistribution des pigments dans ses cellules cutanées."),
        Question(51685, "Quel est le plus gros amphibien jamais découvert?", listOf("Salamandre géante", "Grenouille goliath", "Crapaud géant", "Triton géant"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le crapaud géant, ou Beelzebufo, vivait à Madagascar il y a environ 70 millions d'années et mesurait jusqu'à 40 centimètres, ce qui en fait le plus grand amphibien fossile connu."),
        Question(51686, "Quel animal a le système nerveux le plus complexe?", listOf("Dauphin", "Éléphant", "Pieuvre", "Humain"), 3, "Nature", Difficulty.MEDIUM, explanation = "Le cerveau humain contient environ 86 milliards de neurones, formant un réseau d'une complexité inégalée dans le règne animal."),
        Question(51687, "Combien de sens les humains possèdent-ils?", listOf("3", "4", "5", "7"), 0, "Nature", Difficulty.MEDIUM, explanation = "La croyance populaire en cinq sens (vue, ouïe, toucher, goût, odorat) est une simplification. La science en reconnaît davantage, comme la proprioception et l'équilibre, mais le nombre exact varie selon les classifications."),
        Question(51688, "Quel est l'animal avec le plus grand nombre de dents?", listOf("Requin", "Hippopotame", "Crocodile", "Escargot"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'hippopotame possède jusqu'à 40 dents, mais ce sont principalement ses grandes canines et incisives qui impressionnent."),
        Question(51689, "Combien de dents a un escargot?", listOf("100", "1000", "10000", "20000"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les escargots possèdent une radula, une langue râpeuse couverte de milliers de petites dents chitineuses, pouvant atteindre environ 10 000 dents selon les espèces."),
        Question(51690, "Quel insecte peut sauter le plus haut?", listOf("Sauterelle", "Puce", "Criquet", "Cicada"), 3, "Nature", Difficulty.MEDIUM, explanation = "La cigale (cicada) peut sauter jusqu'à 70 centimètres de haut, soit environ 100 fois sa taille, grâce à ses puissantes pattes arrière."),
        Question(51691, "Combien de fois sa taille peut sauter une puce?", listOf("10x", "50x", "100x", "200x"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les puces peuvent sauter jusqu'à 200 fois leur propre longueur, mais en hauteur, elles atteignent environ 10 fois leur taille grâce à leurs pattes arrière puissantes."),
        Question(51692, "Quel animal peut transformer l'énergie solaire en électricité?", listOf("Anguille électrique", "Poisson électrique", "Raie électrique", "Aucun"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le poisson électrique, comme l'anguille électrique, génère de l'électricité via des cellules spécialisées, mais il ne transforme pas l'énergie solaire. Cette capacité est propre aux plantes et à certains micro-organismes via la photosynthèse."),
        Question(51693, "Combien de volts peut générer une anguille électrique?", listOf("100V", "200V", "400V", "800V"), 2, "Nature", Difficulty.MEDIUM, explanation = "L'anguille électrique peut générer jusqu'à 400 volts pour se défendre ou étourdir ses proies, ce qui est suffisant pour paralyser un humain adulte."),
        Question(51694, "Quel est le plus vieux animal jamais découvert?", listOf("Tortue", "Requin", "Turritopsis dohrnii", "Baleine"), 3, "Nature", Difficulty.MEDIUM, explanation = "Le plus vieil animal jamais découvert est une baleine boréale, dont l'âge a été estimé à 211 ans grâce à l'analyse de ses tissus oculaires."),
        Question(51695, "Combien d'années peut vivre une tortue?", listOf("50", "100", "150", "300"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les tortues terrestres géantes des Galápagos peuvent vivre plus de 100 ans, mais la plupart des espèces de tortues communes atteignent environ 50 ans en moyenne."),
        Question(51696, "Quel animal peut vivre le plus vieux dans le monde sauvage?", listOf("Tortue", "Baleine", "Perroquet", "Humain"), 1, "Nature", Difficulty.MEDIUM, explanation = "La baleine boréale peut vivre plus de 200 ans, ce qui en fait le mammifère le plus longévif connu dans la nature."),
        Question(51697, "Quel est l'arbre le plus vieux du monde?", listOf("Cyprès", "Pin de Bristlecone", "Sequoia", "Châtaignier"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le séquoia géant de Californie, surnommé Mathusalem, est considéré comme l'arbre le plus vieux du monde avec environ 4 850 ans."),
        Question(51698, "Combien d'années a l'arbre le plus vieux du monde?", listOf("3000", "4000", "5000", "6000"), 3, "Nature", Difficulty.MEDIUM, explanation = "Le plus vieil arbre connu est un épicéa nommé Old Tjikko, âgé d'environ 9 550 ans, mais le spécimen non clonal le plus vieux est un pin de Bristlecone âgé de plus de 4 800 ans. La réponse 6000 ans pourrait correspondre à une estimation pour un arbre clonal comme le Pando."),
        Question(51699, "Quel animal a la meilleure audition?", listOf("Chauve-souris", "Dauphin", "Chien", "Oreille humaine"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les chauves-souris utilisent l'écholocation, émettant des ultrasons pour naviguer et chasser dans l'obscurité, ce qui leur confère une ouïe extrêmement développée."),
        Question(51700, "À quelle fréquence les dauphins peuvent-ils entendre?", listOf("20 kHz", "50 kHz", "100 kHz", "150 kHz"), 1, "Nature", Difficulty.MEDIUM, explanation = "Les dauphins perçoivent des ultrasons jusqu'à 50 kHz, bien au-delà des 20 kHz de l'oreille humaine, ce qui leur permet de communiquer et de chasser par écholocalisation."),
        Question(51701, "Quel est l'animal le plus vénimeux au monde?", listOf("Cobra royal", "Serpent brun", "Méduse-boîte", "Grenouille poison"), 2, "Nature", Difficulty.HARD, explanation = "La méduse-boîte possède un venin extrêmement puissant qui peut tuer un humain en quelques minutes, ce qui en fait l'animal le plus vénimeux au monde."),
        Question(51702, "Combien de grenouilles poison faudrait-il pour tuer un humain?", listOf("1", "5", "10", "100"), 3, "Nature", Difficulty.HARD, explanation = "Les grenouilles poison des flèches sécrètent une toxine puissante, la batrachotoxine. Une seule grenouille dorée contient assez de poison pour tuer 10 hommes adultes, donc 100 seraient une surestimation massive."),
        Question(51703, "Quel est le plus grand écosystème du monde?", listOf("Amazonie", "Forêt du Congo", "Taïga", "Récif de corail"), 0, "Nature", Difficulty.HARD, explanation = "L'Amazonie est souvent considérée comme le plus grand écosystème du monde en raison de sa forêt tropicale humide qui s'étend sur environ 6,7 millions de kilomètres carrés, abritant une biodiversité exceptionnelle."),
        Question(51704, "Combien d'espèces animales vivent en Amazonie?", listOf("1 million", "5 millions", "10 millions", "20 millions"), 1, "Nature", Difficulty.HARD, explanation = "L'Amazonie abrite environ 5 millions d'espèces animales, ce qui en fait l'écosystème le plus riche en biodiversité de la planète."),
        Question(51705, "Quel est l'animal terrestre avec la plus grande portée de saut?", listOf("Kangourou", "Léopard", "Lion", "Cerf"), 2, "Nature", Difficulty.HARD, explanation = "Le lion peut sauter jusqu'à 11 mètres de long en un bond, ce qui est la plus grande portée de saut parmi les animaux terrestres."),
        Question(51706, "À quelle distance un kangourou peut-il sauter?", listOf("5m", "10m", "15m", "25m"), 3, "Nature", Difficulty.HARD, explanation = "Les kangourous roux peuvent parcourir jusqu'à 8 mètres en un seul bond, mais des sauts exceptionnels de 13 mètres ont été observés. Le record de 25 mètres mentionné est une donnée rare et non confirmée scientifiquement."),
        Question(51707, "Quel animal peut vivre sans eau le plus longtemps?", listOf("Chameau", "Koudou", "Oryx", "Girafe"), 0, "Nature", Difficulty.HARD, explanation = "Le chameau peut survivre jusqu'à deux semaines sans eau grâce à ses bosses qui stockent des réserves de graisse et à son métabolisme adapté à la déshydratation."),
        Question(51708, "Combien d'années un oryx peut-il survivre sans eau?", listOf("1", "3", "5", "10"), 1, "Nature", Difficulty.HARD, explanation = "L'oryx peut survivre jusqu'à trois ans sans boire, car il tire l'eau nécessaire de la végétation qu'il consomme et adapte son métabolisme pour limiter les pertes hydriques."),
        Question(51710, "Combien de kilomètres carrés fait le Sahara?", listOf("5 millions", "8 millions", "12 millions", "15 millions"), 3, "Nature", Difficulty.HARD, explanation = "Le Sahara est le plus grand désert chaud du monde, couvrant environ 9,2 millions de kilomètres carrés, soit près de 15 millions si l'on inclut les zones désertiques adjacentes."),
        Question(51711, "Quel est le plus grand réservoir d'eau douce du monde?", listOf("Lac Baïkal", "Grands Lacs", "Lac Victoria", "Lac Tanganyika"), 0, "Nature", Difficulty.HARD, explanation = "Le lac Baïkal, en Sibérie, contient environ 20 % des eaux douces non gelées de la planète, ce qui en fait le plus grand réservoir d'eau douce liquide au monde."),
        Question(51712, "Combien de pour cent de l'eau douce mondiale se trouve au Baïkal?", listOf("10%", "20%", "30%", "40%"), 1, "Nature", Difficulty.HARD, explanation = "Le lac Baïkal est le plus grand réservoir d'eau douce liquide de la planète, contenant environ 20 % des réserves mondiales."),
        Question(51713, "Quel animal peut manger le plus de nourriture en une journée?", listOf("Baleine", "Éléphant", "Hippopotame", "Requin"), 2, "Nature", Difficulty.HARD, explanation = "L'hippopotame peut consommer jusqu'à 40 kg d'herbe par jour, ce qui en fait l'un des plus gros mangeurs terrestres en une seule journée."),
        Question(51714, "Combien de kilos une baleine peut-elle manger par jour?", listOf("2000", "5000", "8000", "10000"), 3, "Nature", Difficulty.HARD, explanation = "Une baleine bleue adulte peut consommer jusqu'à 4 tonnes de krill par jour, soit environ 10 000 kilos, pour subvenir à ses besoins énergétiques massifs."),
        Question(51716, "Combien de mètres peut mesurer une crinière du lion?", listOf("10m", "20m", "30m", "50m"), 1, "Nature", Difficulty.HARD, explanation = "La crinière du lion peut atteindre jusqu'à 20 mètres de long, mais il s'agit en réalité d'une méduse, la Cyanea capillata, et non du mammifère."),
        Question(51717, "Quel animal a le plus grand nombre de dents adultes?", listOf("Requin blanc", "Hippopotame", "Crocodile", "Éléphant"), 2, "Nature", Difficulty.HARD, explanation = "Le crocodile peut avoir jusqu'à 80 dents à l'âge adulte, et il les renouvelle plusieurs fois dans sa vie, ce qui en fait le mammifère avec le plus grand nombre de dents."),
        Question(51719, "Quel est le plus haut volcan actif du monde?", listOf("Mont-Blanc", "Cotopaxi", "Villarrica", "Ojos del Salado"), 0, "Nature", Difficulty.HARD, explanation = "Le Mont-Blanc n'est pas un volcan actif, mais le plus haut sommet des Alpes. La bonne réponse serait plutôt l'Ojos del Salado, dans les Andes, qui culmine à 6 893 mètres."),
        Question(51720, "À quelle altitude se trouve l'Ojos del Salado?", listOf("6000m", "6500m", "7000m", "7500m"), 1, "Nature", Difficulty.HARD, explanation = "L'Ojos del Salado est le plus haut volcan actif du monde, culminant à 6 893 mètres, mais sa principale altitude de référence est souvent donnée à 6 500 mètres dans certains contextes géographiques."),
        Question(51722, "Combien de milliards de tonnes de glace se trouvent en Antarctique?", listOf("10", "50", "100", "200"), 3, "Nature", Difficulty.HARD, explanation = "L'Antarctique contient environ 200 milliards de tonnes de glace, ce qui représente près de 90 % de la glace terrestre et 70 % de l'eau douce de la planète."),
        Question(51723, "Quel est l'animal le plus rare du monde?", listOf("Panda", "Lynx ibérique", "Kakapo", "Rhinocéros blanc du nord"), 0, "Nature", Difficulty.HARD, explanation = "Le panda géant est considéré comme l'un des animaux les plus rares au monde, avec une population sauvage estimée à moins de 2 000 individus, principalement en raison de la perte de son habitat naturel en Chine."),
        Question(51724, "Combien de rhinocéros blancs du nord restent dans le monde?", listOf("1", "2", "3", "5"), 1, "Nature", Difficulty.HARD, explanation = "Il ne reste que deux rhinocéros blancs du nord, une femelle et sa fille, vivant sous protection armée au Kenya. L'espèce est fonctionnellement éteinte depuis la mort du dernier mâle en 2018."),
        Question(51725, "Quel est le plus grand crustacé jamais découvert?", listOf("Crabe géant du Japon", "Homard américain", "Araignée de mer géante", "Crabe royal"), 2, "Nature", Difficulty.HARD, explanation = "L'araignée de mer géante du Japon (Macrocheira kaempferi) détient le record du plus grand crustacé, avec une envergure de pattes pouvant atteindre 3,8 mètres.")
    )

    private fun mythologie(): List<Question> = listOf(
        Question(51726, "Quel dieu romain équivaut à Zeus grec?", listOf("Mars", "Jupiter", "Mercure", "Vénus"), 0, "Mythologie", Difficulty.EASY, explanation = "Mars est le dieu romain de la guerre, tandis que Zeus est le roi des dieux grecs. L'équivalent romain de Zeus est Jupiter."),
        Question(51727, "Combien de têtes avait l'Hydre de Lerne?", listOf("3", "5", "7", "9"), 1, "Mythologie", Difficulty.EASY, explanation = "L'Hydre de Lerne est généralement représentée avec neuf têtes dans la mythologie grecque, mais certaines versions en comptent cinq, sept ou même cent. Le nombre varie selon les récits."),
        Question(51728, "Quel monstre garde les portes du Tartare?", listOf("Cerbère", "Minotaure", "Chimère", "Dragon"), 2, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, la Chimère est un monstre hybride crachant du feu, mais ce n'est pas elle qui garde le Tartare : c'est Cerbère, le chien à trois têtes."),
        Question(51729, "Combien de têtes a Cerbère?", listOf("1", "2", "3", "4"), 3, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Cerbère est le chien à trois têtes gardant les Enfers. La réponse 4 est fausse car il en a trois, pas quatre."),
        Question(51730, "Quel titan a été puni à traverser les âges?", listOf("Cronos", "Atlas", "Prométhée", "Océan"), 0, "Mythologie", Difficulty.EASY, explanation = "Cronos, le titan qui a dévoré ses enfants, a été puni par Zeus en étant enfermé dans le Tartare, un abîme souterrain, pour l'éternité."),
        Question(51731, "Quel est le nom du dieu des enfers romain?", listOf("Charon", "Pluton", "Hadès", "Poséidon"), 1, "Mythologie", Difficulty.EASY, explanation = "Pluton est l'équivalent romain du dieu grec Hadès, souverain des enfers et des morts."),
        Question(51732, "Quel arme Zeus utilisait-il pour punir?", listOf("Épée", "Éclair", "Trident", "Arc"), 2, "Mythologie", Difficulty.EASY, explanation = "Le trident est en réalité l'attribut de Poséidon, dieu de la mer, tandis que Zeus utilisait la foudre comme arme pour punir."),
        Question(51733, "Quel est le nom du cheval dans la légende grecque?", listOf("Cheval de Trojane", "Cheval de Troie", "Cheval d'Ilion", "Cheval d'Athènes"), 3, "Mythologie", Difficulty.EASY, explanation = "Le cheval d'Athènes est une référence au cheval de Troie, bien que la légende grecque ne mentionne pas de nom spécifique pour cet animal."),
        Question(51734, "Combien de guerriers grecs se sont cachés dans le Cheval de Troie?", listOf("100", "500", "1000", "2000"), 0, "Mythologie", Difficulty.EASY, explanation = "Selon l'épopée de l'Énéide de Virgile, une centaine de guerriers grecs, dont Ulysse, se cachèrent dans le cheval de Troie pour infiltrer la ville."),
        Question(51735, "Quel dieu nordique a perdu un œil?", listOf("Thor", "Odin", "Loki", "Heimdall"), 1, "Mythologie", Difficulty.EASY, explanation = "Odin a sacrifié son œil dans le puits de Mimir pour acquérir la sagesse et la connaissance de l'univers."),
        Question(51736, "Quel serpent nordique mord l'arbre Yggdrasil?", listOf("Jörmungandr", "Níðhöggr", "Skaði", "Fenrir"), 2, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie nordique, Skaði est une géante associée à la chasse et aux montagnes, mais ce n'est pas elle qui mord Yggdrasil. Le serpent qui ronge les racines de l'arbre cosmique est Níðhöggr."),
        Question(51737, "Quel est le nom de l'épée magique d'Excalibur?", listOf("Caliburn", "Gueule d'Âme", "Kusanagi", "Précieuse"), 3, "Mythologie", Difficulty.EASY, explanation = "Excalibur est le nom de l'épée légendaire du roi Arthur, et non un type d'épée. Le terme \"Précieuse\" est ici une erreur, car il ne correspond à aucune épée magique de la mythologie arthurienne."),
        Question(51738, "Qui a forgé Mjolnir, le marteau de Thor?", listOf("Les Nains", "Héphaïstos", "Surtir", "Les Géants"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie nordique, le marteau Mjolnir a été forgé par les frères nains Brokk et Sindri, dans le cadre d'un pari avec Loki."),
        Question(51739, "Quel roi maudit a épousé sa propre mère?", listOf("Ares", "Œdipe", "Persée", "Achille"), 1, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Œdipe accomplit la prophétie en tuant son père Laïos et en épousant sa mère Jocaste, ignorant leur identité."),
        Question(51740, "Quel héros a tué Méduse la Gorgone?", listOf("Thésée", "Persée", "Hercule", "Ajax"), 2, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, c'est Persée qui a décapité Méduse, et non Hercule."),
        Question(51741, "Combien de labeurs Hercule doit-il accomplir?", listOf("10", "12", "15", "20"), 3, "Mythologie", Difficulty.EASY, explanation = "Hercule doit accomplir douze travaux, et non vingt. Le nombre vingt vient peut-être d'une confusion avec d'autres épreuves ou récits mythologiques."),
        Question(51742, "Quel est le dernier des 12 travaux d'Hercule?", listOf("Capturer Cerbère", "Obtenir les pommes d'or", "Tuer le lion", "Capturer la biche"), 0, "Mythologie", Difficulty.EASY, explanation = "Le douzième et dernier travail imposé à Hercule par Eurysthée était de capturer Cerbère, le chien à trois têtes gardien des Enfers, sans utiliser d'armes."),
        Question(51743, "Quel dieu égyptien a la tête d'un chacal?", listOf("Horus", "Anubis", "Thoth", "Set"), 1, "Mythologie", Difficulty.EASY, explanation = "Anubis est le dieu égyptien de la momification et de l'au-delà, représenté avec une tête de chacal en raison du comportement de cet animal fréquentant les nécropoles."),
        Question(51744, "Quel dieu égyptien est le soleil?", listOf("Ra", "Horus", "Amun", "Ptah"), 2, "Mythologie", Difficulty.EASY, explanation = "Amun est le dieu du soleil caché, souvent associé à Rê pour former Amun-Rê, le roi des dieux dans la mythologie égyptienne."),
        Question(51745, "Combien de dieux principaux comptait le panthéon égyptien?", listOf("9", "12", "15", "20"), 3, "Mythologie", Difficulty.EASY, explanation = "Le panthéon égyptien comptait environ 20 dieux principaux, incluant Rê, Osiris, Isis et Horus, bien que le nombre exact varie selon les époques et les régions."),
        Question(51746, "Quel titan a mangé ses propres enfants?", listOf("Chronos", "Cronos", "Océan", "Japet"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Chronos, craignant une prophétie annonçant qu'il serait détrôné par ses enfants, les dévorait à leur naissance."),
        Question(51747, "Quel est le nom du monstre mi-homme mi-taureau?", listOf("Centaure", "Minotaure", "Chimère", "Sphinx"), 1, "Mythologie", Difficulty.EASY, explanation = "Le Minotaure, enfermé dans le Labyrinthe de Crète, était le fruit de l'union de Pasiphaé avec un taureau envoyé par Poséidon."),
        Question(51748, "Dans quel labyrinthe le Minotaure était-il enfermé?", listOf("Crète", "Thèbes", "Dédale", "Knossos"), 2, "Mythologie", Difficulty.EASY, explanation = "Dédale a construit le labyrinthe pour enfermer le Minotaure, créature mi-homme mi-taureau, sur ordre du roi Minos en Crète."),
        Question(51749, "Quel est le nom de la déesse la mère de tous les dieux?", listOf("Rhéa", "Théthys", "Mnémosyne", "Thémis"), 3, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Thémis est la titanide de la justice et de l'ordre divin, souvent considérée comme une mère des dieux pour son rôle dans la génération des divinités."),
        Question(51750, "Quel dieu hindou a plusieurs bras?", listOf("Brahma", "Vishnou", "Shiva", "Ganesh"), 0, "Mythologie", Difficulty.EASY, explanation = "Brahma est souvent représenté avec quatre têtes et quatre bras, symbolisant sa connaissance des quatre Vedas et des quatre directions."),
        Question(51751, "Combien de bras Shiva le Dieu de la Danse possède-t-il généralement?", listOf("2", "3", "4", "6"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Dans l'iconographie hindoue, Shiva Nataraja, le dieu de la danse cosmique, est généralement représenté avec quatre bras, et non trois."),
        Question(51752, "Quel dieu hindou a une tête d'éléphant?", listOf("Hanuman", "Ganesh", "Krishn", "Brahma"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Ganesh, et non Krishna, est le dieu hindou à tête d'éléphant, fils de Shiva et Parvati, connu comme le dieu de la sagesse et des commencements."),
        Question(51753, "Quel monstre gardait les pommes d'or des Hespérides?", listOf("Dragon", "Serpent", "Griffon", "Cerbère"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Cerbère gardait les portes des Enfers, non les pommes d'or des Hespérides. C'est un dragon à cent têtes qui veillait sur ce jardin sacré."),
        Question(51754, "Quel est le nom du serpent gardien des pommes d'or?", listOf("Python", "Ladon", "Apophis", "Jörmungandr"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Python était un serpent monstrueux qui gardait l'oracle de Delphes et les pommes d'or du jardin des Hespérides."),
        Question(51755, "Quel héros a accompli le voyage des Argonautes?", listOf("Achille", "Jason", "Persée", "Héraclès"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Jason a mené l'expédition des Argonautes à bord du navire Argo pour conquérir la Toison d'or."),
        Question(51756, "Quel était l'objectif de la quête des Argonautes?", listOf("Toison d'Or", "Pommes d'Or", "Épée Sacrée", "Graal"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, la quête des Argonautes visait à rapporter la Toison d'or, et non une épée sacrée."),
        Question(51757, "Quel roi gréco-romain a conquis le monde?", listOf("Achille", "Hercule", "Alexandre", "Énée"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie gréco-romaine, Énée est un héros troyen qui, selon la légende, a survécu à la guerre de Troie et a voyagé pour fonder la lignée romaine, mais il n'a pas conquis le monde."),
        Question(51758, "Quel est le symbole de Poséidon?", listOf("Épée", "Éclair", "Trident", "Arc"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Poséidon est souvent représenté avec un trident, et non une épée, qui symbolise son pouvoir sur les mers et les tremblements de terre."),
        Question(51759, "Quel est le symbole d'Athéna?", listOf("Hibou", "Chouette", "Aigle", "Sphinx"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Athéna, déesse de la sagesse et de la guerre stratégique, avait pour emblème la chouette, symbole de la connaissance et de la clairvoyance."),
        Question(51760, "Quel dieu valkyrie servait dans la mythologie nordique?", listOf("Frigg", "Odin", "Heimdall", "Skadi"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Heimdall est le dieu gardien du Bifröst, le pont arc-en-ciel, et non une valkyrie. Les valkyries sont des servantes d'Odin, et non des dieux."),
        Question(51761, "Quel est le nom de l'arbre cosmique nordique?", listOf("Yggdrasil", "Bifrost", "Asgard", "Midgard"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie nordique, l'arbre cosmique est Yggdrasil, et non Midgard, qui désigne le monde des humains."),
        Question(51762, "Combien de mondes sont reliés par Yggdrasil?", listOf("3", "5", "7", "9"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie nordique, l'arbre cosmique Yggdrasil relie neuf mondes, mais les trois principaux sont Asgard, Midgard et Helheim."),
        Question(51763, "Quel est le nom de la fin du monde dans la mythologie nordique?", listOf("Apocalypse", "Ragnarok", "Gotterdammerung", "Apocalypsis"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie nordique, Ragnarök désigne la série d'événements apocalyptiques incluant une grande bataille entre les dieux et les géants, menant à la destruction et à la renaissance du monde."),
        Question(51764, "Quel loup va dévorer Odin lors du Ragnarok?", listOf("Fenrir", "Jörmungandr", "Nidhogg", "Garmr"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Nidhogg est un dragon, non un loup, qui ronge les racines d'Yggdrasil. Le loup qui dévore Odin lors du Ragnarök est Fenrir."),
        Question(51765, "Quel dieu des enfers était mari de Perséphone?", listOf("Pluton", "Hadès", "Charon", "Erebus"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Hadès, le dieu des enfers, enleva Perséphone pour en faire son épouse, mais Erebus est une divinité primordiale des ténèbres, non son mari."),
        Question(51766, "Combien de mois Perséphone doit-elle passer aux enfers?", listOf("3", "6", "9", "12"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Selon le mythe grec, Perséphone passe six mois aux Enfers avec Hadès, mais le nombre de mois varie selon les versions ; la réponse 3 correspond à une variante où elle y séjourne trois mois, symbolisant l'hiver."),
        Question(51767, "Quel est le fils de Héra et Zeus?", listOf("Arès", "Apollon", "Héphaïstos", "Hermès"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Apollon est le fils de Zeus et de Léto, et non d'Héra. Héra était l'épouse de Zeus mais n'a pas donné naissance à Apollon."),
        Question(51768, "Quel dieu de la mer était le père de Persée?", listOf("Océan", "Poséidon", "Amphitrite", "Tritone"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Amphitrite est la déesse de la mer, épouse de Poséidon, et non le père de Persée. Persée est en réalité le fils de Zeus et de Danaé."),
        Question(51769, "Quel est le nom du fils de Poséidon et de la Méduse?", listOf("Chrysaor", "Pégase", "Gorgone", "Chimère"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Poséidon et Méduse eurent pour enfants Pégase et Chrysaor, mais pas la Chimère, qui est une créature issue de la mythologie grecque, fille de Typhon et d'Échidna."),
        Question(51770, "Quel animal magique était le compagnon d'Apollon?", listOf("Corbeau", "Coq", "Lion", "Serpent"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, le corbeau était l'oiseau sacré d'Apollon, souvent associé à la divination et messager du dieu."),
        Question(51771, "Quel dieu jouait de la lyre?", listOf("Apollon", "Orphée", "Hermès", "Mercure"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Orphée, figure de la mythologie grecque, était un musicien et poète légendaire dont le talent pour la lyre charmait même les dieux et les créatures des enfers."),
        Question(51772, "Quel est le vrai nom du héros Achille dans l'épopée?", listOf("Pélée", "Achillée", "Achillieus", "Nérée"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Dans les textes grecs anciens, notamment l’Iliade, le héros est appelé Achilleus, forme hellénisée de son nom, qui a été latinisée en Achille en français."),
        Question(51773, "Quel point faible Achille avait-il?", listOf("Cœur", "Talon", "Tête", "Genou"), 3, "Mythologie", Difficulty.MEDIUM, explanation = "Selon la légende, sa mère Thétis le plongea dans le Styx pour le rendre invulnérable, mais le talon par lequel elle le tenait resta vulnérable."),
        Question(51774, "Quel héros troyen a fui sa ville?", listOf("Hector", "Énée", "Priam", "Paris"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Hector est le héros troyen qui a combattu les Grecs, mais il a fui momentanément Achille avant de l'affronter et d'être tué."),
        Question(51775, "Quel est le fondateur légendaire de Rome selon la légende?", listOf("Énée", "Romulus", "Rémus", "Tarquin"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Selon la légende, Romulus et son frère jumeau Rémus, fils de Mars et de Rhéa Silvia, fondèrent Rome en 753 av. J.-C. après avoir été allaités par une louve. Romulus tua Rémus lors d'une dispute et devint le premier roi de Rome."),
        Question(51776, "Quel est le nom du caducée d'Hermès?", listOf("Bâton", "Caducée ailé", "Trident", "Lyre"), 2, "Mythologie", Difficulty.HARD, explanation = "Le caducée d'Hermès est un bâton entouré de deux serpents, souvent confondu avec le trident de Poséidon, mais le trident est l'attribut du dieu des mers."),
        Question(51777, "Quel dieu chinois représente la richesse?", listOf("Kuan Yu", "Fukurokuju", "Hotei", "Ganesha"), 3, "Mythologie", Difficulty.HARD, explanation = "Ganesha est un dieu hindou, pas chinois. Dans la mythologie chinoise, le dieu de la richesse est Caishen."),
        Question(51778, "Combien de déesses japonaises de la tempête existait-il?", listOf("1", "2", "3", "4"), 0, "Mythologie", Difficulty.HARD, explanation = "Susanoo, le dieu de la tempête, est une divinité masculine. Il n'existe pas de déesse de la tempête dans la mythologie japonaise."),
        Question(51779, "Quel est le nom de la plus grande déesse du soleil?", listOf("Amaterasu", "Tsukuyomi", "Susanoo", "Izanami"), 1, "Mythologie", Difficulty.HARD, explanation = "Tsukuyomi est en réalité le dieu de la Lune dans la mythologie japonaise, et non une déesse du soleil. La plus grande déesse du soleil est Amaterasu, sa sœur."),
        Question(51780, "Quel dieu mésopotamien créa l'humanité?", listOf("Enlil", "Enuma Elish", "Mardouk", "Anunnaki"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans l'épopée babylonienne de la création, l'Enuma Elish, Mardouk tue Tiamat et façonne les humains avec le sang du dieu rebelle Kingu pour servir les dieux."),
        Question(51781, "Quel est le nom du déluge dans la mythologie mésopotamienne?", listOf("Inondation", "Abzu", "Dilmun", "Deluge d'Atrahasis"), 3, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie mésopotamienne, le récit du Déluge d'Atrahasis raconte comment le dieu Enki avertit le héros Atrahasis de construire un bateau pour survivre à une inondation envoyée par les dieux."),
        Question(51782, "Quel dieu aztèque demandait des sacrifices?", listOf("Huitzilopochtli", "Quetzalcóatl", "Tezcatlipoca", "Xipe Totec"), 0, "Mythologie", Difficulty.HARD, explanation = "Huitzilopochtli, dieu solaire et de la guerre aztèque, exigeait des sacrifices humains pour nourrir le soleil et assurer le cycle du jour."),
        Question(51783, "Quel est le panthéon des dieux romains?", listOf("Olympe", "Capitole", "Forum", "Panthéon"), 1, "Mythologie", Difficulty.HARD, explanation = "Le Capitole était la colline sacrée de Rome où se dressait le temple principal dédié à Jupiter, Junon et Minerve, formant le noyau du panthéon romain."),
        Question(51784, "Quel dieu romain équivaut à Apollon?", listOf("Apollo", "Mars", "Mercure", "Vulcain"), 2, "Mythologie", Difficulty.HARD, explanation = "Apollon est un dieu grec, et son équivalent romain est Apollon lui-même, car les Romains ont conservé son nom et ses attributs sans le renommer. Mercure correspond à Hermès."),
        Question(51785, "Quel est le nom de la déesse de la sagesse grecque?", listOf("Héra", "Athéna", "Métis", "Déméter"), 3, "Mythologie", Difficulty.HARD, explanation = "Déméter est la déesse de l'agriculture et des moissons dans la mythologie grecque, non de la sagesse. La déesse de la sagesse est Athéna."),
        Question(51786, "Quel est le symbole de Zeus?", listOf("Trident", "Éclair", "Couronne", "Sceptre"), 0, "Mythologie", Difficulty.HARD, explanation = "Le trident est en réalité l'attribut de Poséidon, dieu de la mer. Le symbole de Zeus est le foudre, une arme représentant la foudre."),
        Question(51787, "Quel dieu grec était le messager des dieux?", listOf("Apollon", "Hermès", "Ares", "Vulcain"), 1, "Mythologie", Difficulty.HARD, explanation = "Hermès était le messager des dieux dans la mythologie grecque, connu pour sa vitesse et son rôle de guide des âmes vers les Enfers."),
        Question(51788, "Quel est le nom du peuple des géants dans la mythologie scandinave?", listOf("Géants", "Jotun", "Titan", "Gogmagog"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie scandinave, les géants sont appelés les Jötunn, et non les Titans, qui appartiennent à la mythologie grecque."),
        Question(51789, "Quel est le vrai nome du Cyclope d'Ulysse?", listOf("Polyphème", "Gela", "Cyclops", "Monope"), 3, "Mythologie", Difficulty.HARD, explanation = "Dans l'Odyssée, le Cyclope est nommé Polyphème, mais le nom \"Monope\" (un seul œil) est parfois utilisé comme traduction littérale de son apparence."),
        Question(51790, "Combien d'années Ulysse a-t-il mis à rentrer chez lui?", listOf("5", "7", "10", "15"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans l'Odyssée d'Homère, Ulysse met dix ans à revenir à Ithaque après la guerre de Troie, dont cinq ans sont consacrés à ses aventures et errances."),
        Question(51791, "Quel est le nom de la magicienne qui gardait Ulysse?", listOf("Calypso", "Circé", "Sirène", "Naïade"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans l'Odyssée d'Homère, Circé est une magicienne qui retient Ulysse et ses compagnons sur son île d'Ééa, les transformant en animaux."),
        Question(51792, "Quel est le nom du guerrier Trojan rival d'Achille?", listOf("Paris", "Hector", "Ajax", "Énée"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Ajax est un héros troyen, fils de Télamon, qui s'oppose à Achille lors de la guerre de Troie, notamment dans l'Iliade d'Homère."),
        Question(51793, "Quel dieu a créé Pandore?", listOf("Héphaïstos", "Apollon", "Hèrmes", "Zeus"), 3, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, c'est Zeus qui ordonna la création de Pandore, la première femme, pour punir l'humanité après le vol du feu par Prométhée."),
        Question(51794, "Quel est le contenu de la boîte de Pandore?", listOf("Or", "Maux", "Lumière", "Pouvoirs"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, la boîte de Pandore contenait tous les maux de l'humanité, mais aussi l'espoir. Le mot \"or\" est une erreur, car le mythe ne mentionne pas ce métal précieux."),
        Question(51795, "Quel est le seul bien qui restait dans la boîte?", listOf("Amour", "Espoir", "Joie", "Santé"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans le mythe grec de Pandore, tous les maux s'échappèrent de la boîte qu'elle ouvrit, ne laissant que l'Espoir au fond."),
        Question(51796, "Quel roi de Thèbes a commis l'inceste?", listOf("Laïus", "Œdipe", "Créon", "Étéocle"), 2, "Mythologie", Difficulty.HARD, explanation = "Créon devient roi de Thèbes après la mort d'Œdipe, mais ce dernier est celui qui a commis l'inceste en épousant sa mère Jocaste. Créon est souvent confondu avec Œdipe dans ce mythe."),
        Question(51797, "Quel est le nom du sphinx de Thèbes?", listOf("Phix", "Sphinx", "Créon", "Laïus"), 3, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, le sphinx de Thèbes terrorisait la cité en posant une énigme aux voyageurs. Œdipe résolut l'énigme, ce qui causa la mort du sphinx et permit à Œdipe d'épouser la reine Jocaste, veuve du roi Laïus."),
        Question(51798, "Quel dieu a été transformé en arbre?", listOf("Daphné", "Apollon", "Pan", "Hermès"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Daphné est une nymphe qui, pour échapper aux avances d'Apollon, fut transformée en laurier par son père, le dieu fleuve Pénée."),
        Question(51799, "Quel arbre Daphné est-elle devenue?", listOf("Laurier", "Chêne", "Hêtre", "Pin"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Daphné fut transformée en laurier par son père, le dieu fleuve Pénée, pour échapper aux avances d'Apollon."),
        Question(51800, "Quel est le nombre de monstres terrifiants dans la mythologie?", listOf("10", "50", "100", "500"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, les hécatonchires étaient des géants à cent bras et cinquante têtes, enfants d'Ouranos et Gaïa, considérés comme des monstres terrifiants.")
    )

    private fun gastronomie(): List<Question> = listOf(
        Question(51801, "Quel est le plat le plus cher du monde?", listOf("Caviar", "Truffe", "Or 24k", "Safrán"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le caviar, notamment le beluga ou l'almas iranien, peut atteindre des prix exorbitants, jusqu'à plusieurs milliers d'euros le kilo, en raison de la rareté des esturgeons et du processus de récolte minutieux."),
        Question(51802, "Quel est le pays d'origine de la paella?", listOf("Portugal", "Espagne", "Italie", "Grèce"), 1, "Gastronomie", Difficulty.EASY, explanation = "La paella est un plat traditionnel valencien, originaire de la région de Valence en Espagne, à base de riz, de safran et de divers ingrédients comme les fruits de mer ou la viande."),
        Question(51803, "Quel ingrédient rend le sushi possible?", listOf("Riz", "Riz vinaigré", "Riz bouilli", "Riz cuit vapeur"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le riz bouilli, assaisonné de vinaigre, sucre et sel, est l'élément central du sushi car il sert de base pour lier les autres ingrédients comme le poisson cru ou les légumes."),
        Question(51804, "Combien d'étoiles Michelin un restaurant peut-il avoir au maximum?", listOf("2", "3", "5", "10"), 3, "Gastronomie", Difficulty.EASY, explanation = "Le guide Michelin n'attribue que trois étoiles maximum par restaurant. La réponse 10 est donc erronée, car aucun établissement ne peut en obtenir davantage."),
        Question(51805, "Quel est le restaurant français 3 étoiles Michelin le plus ancien?", listOf("L'Astrance", "L'Arpège", "Le Bernardin", "Chez Bocuse"), 0, "Gastronomie", Difficulty.EASY, explanation = "L'Astrance, dirigé par Pascal Barbot, a obtenu sa troisième étoile Michelin en 2007 et l'a conservée jusqu'à sa fermeture en 2024, ce qui en faisait l'un des triples étoilés les plus anciens de Paris."),
        Question(51806, "Quel aliment est le plus cher au gramme?", listOf("Caviar", "Safran", "Truffe blanche", "Or 24k comestible"), 1, "Gastronomie", Difficulty.EASY, explanation = "Le safran est l'épice la plus chère au monde car sa production nécessite la récolte manuelle de milliers de stigmates de crocus, avec environ 150 000 fleurs pour un kilo."),
        Question(51807, "Combien coûte un gramme de safran?", listOf("1 euro", "5 euros", "10 euros", "20 euros"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le safran est l'épice la plus chère au monde en raison de sa récolte manuelle minutieuse : il faut environ 150 000 fleurs de crocus pour obtenir un kilo, soit un gramme à 10 euros."),
        Question(51808, "Quel champagne est le plus prestigieux?", listOf("Dom Pérignon", "Krug", "Cristal", "Kosta Boda"), 3, "Gastronomie", Difficulty.EASY, explanation = "Kosta Boda n'est pas un champagne mais une célèbre cristallerie suédoise, souvent confondue avec des marques de luxe. Le champagne le plus prestigieux est généralement considéré comme Dom Pérignon ou Krug."),
        Question(51809, "Quel est l'aliment le plus ancien connu de l'humanité?", listOf("Blé", "Orge", "Riz", "Avoine"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le blé est considéré comme l'un des premiers aliments cultivés par l'homme, avec des traces de sa domestication datant d'environ 10 000 ans au Proche-Orient."),
        Question(51810, "Quel est le fromage le plus cher du monde?", listOf("Parmigiano", "Wookey Hole", "Moose Cheese", "Gold Leaf Cheese"), 1, "Gastronomie", Difficulty.EASY, explanation = "Le Wookey Hole est un fromage de chèvre britannique produit dans la grotte de Wookey Hole, dont l'affinage souterrain rare et le processus artisanal le rendent extrêmement coûteux."),
        Question(51811, "En combien d'années le Parmigiano-Reggiano doit-il être affiné?", listOf("1", "2", "3", "5"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le cahier des charges de l'appellation d'origine protégée impose un affinage minimum de 12 mois, mais la mention \"stravecchio\" nécessite au moins 3 ans."),
        Question(51812, "Quel aliment n'a pas d'expiration légale?", listOf("Miel", "Sel", "Sucre", "Tous les trois"), 3, "Gastronomie", Difficulty.EASY, explanation = "Le miel, le sel et le sucre sont des aliments qui ne périment pas grâce à leurs propriétés naturelles de conservation, ce qui explique l'absence de date limite de consommation légale pour ces produits."),
        Question(51813, "Quel miel est le plus cher du monde?", listOf("Manuka", "Acacia", "Châtaigne", "Rucola"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le miel de Manuka, produit en Nouvelle-Zélande à partir du nectar de l’arbre Manuka, est réputé pour ses propriétés antibactériennes uniques et sa rareté, ce qui en fait le plus cher au monde."),
        Question(51814, "Combien coûte un kilogramme de miel Manuka?", listOf("50 euros", "100 euros", "500 euros", "1000 euros"), 1, "Gastronomie", Difficulty.EASY, explanation = "Le miel de Manuka, produit en Nouvelle-Zélande à partir du nectar de l'arbre Manuka, est réputé pour ses propriétés antibactériennes uniques, ce qui justifie son prix élevé, souvent autour de 100 euros le kilogramme."),
        Question(51815, "Quel est le pays originel du curry?", listOf("Thaïlande", "Inde", "Vietnam", "Indonésie"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le curry est originaire d'Inde, mais la question comporte une erreur car la bonne réponse est le Vietnam, pays où le curry a été adapté avec des influences locales."),
        Question(51816, "Combien de variétés de curry existe-t-il?", listOf("5", "10", "20", "50+"), 3, "Gastronomie", Difficulty.EASY, explanation = "Le curry est un terme générique qui englobe une multitude de plats et de mélanges d'épices, variant selon les régions d'Asie, avec plus de 50 recettes traditionnelles recensées."),
        Question(51817, "Quel aliment provoque le plus de décès par allergie?", listOf("Cacahuètes", "Crustacés", "Œufs", "Lait"), 0, "Gastronomie", Difficulty.EASY, explanation = "Les cacahuètes sont responsables de la majorité des décès par allergie alimentaire en raison de leur capacité à déclencher des réactions anaphylactiques sévères, même à très faible dose."),
        Question(51818, "Quel est le fruit le plus nutritif du monde?", listOf("Banane", "Avocat", "Noix de coco", "Olive"), 1, "Gastronomie", Difficulty.EASY, explanation = "L'avocat est souvent considéré comme le fruit le plus nutritif en raison de sa forte teneur en graisses saines, en fibres, en vitamines et en minéraux."),
        Question(51819, "Quel légume a été découvert en Amérique?", listOf("Carotte", "Pomme de terre", "Brocoli", "Oignon"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le brocoli est un légume originaire d'Italie, cultivé depuis l'Antiquité romaine, et non d'Amérique. Il a été introduit en Amérique du Nord par des immigrants italiens au 20e siècle."),
        Question(51820, "Combien de calories contient un kilogramme de graisse?", listOf("4000", "6000", "9000", "12000"), 3, "Gastronomie", Difficulty.EASY, explanation = "Un kilogramme de graisse corporelle équivaut à environ 7 700 calories, mais la valeur de 12 000 calories est souvent citée pour la graisse pure (tissu adipeux). Cette différence vient du fait que le tissu adipeux contient aussi de l'eau et des protéines."),
        Question(51821, "Quel épice est le plus utilisé au monde?", listOf("Poivre", "Sel", "Cannelle", "Curcuma"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le poivre est l'épice la plus consommée dans le monde, devant le piment et le curcuma, en raison de son utilisation quotidienne dans de nombreuses cuisines pour assaisonner les plats."),
        Question(51822, "Quel est le plus vieux restaurant du monde?", listOf("Guinness Records", "St. Peter Stiftskulinarium", "Casa Botín", "Al Ikhlas"), 1, "Gastronomie", Difficulty.EASY, explanation = "Fondé en 803, le St. Peter Stiftskulinarium à Salzbourg, en Autriche, est officiellement reconnu comme le plus vieux restaurant du monde encore en activité."),
        Question(51823, "En quelle année le plus vieux restaurant a-t-il ouvert?", listOf("800", "900", "1000", "1100"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le Stiftskeller St. Peter à Salzbourg, en Autriche, est considéré comme le plus vieux restaurant du monde, mentionné pour la première fois dans des documents datant de l'an 803, mais son ouverture officielle est souvent associée à l'an 1000."),
        Question(51824, "Quel est le plat national français?", listOf("Coq au vin", "Escalope", "Béarnaise", "Aucun officiel"), 3, "Gastronomie", Difficulty.EASY, explanation = "La France n'a jamais désigné officiellement de plat national par une loi ou un décret, contrairement à d'autres pays comme l'Italie avec les pâtes. Le pot-au-feu, la blanquette ou le bœuf bourguignon sont souvent cités, mais aucun n'a de statut officiel."),
        Question(51825, "Quel est le plat national des États-Unis?", listOf("Hot-dog", "Hamburger", "Aucun officiel", "Tarte aux pommes"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le hot-dog est souvent considéré comme le plat national des États-Unis en raison de sa popularité dans les stades de baseball et les fêtes du 4 juillet."),
        Question(51827, "Combien de variétés de riz existent?", listOf("100", "500", "1000", "5000"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Le riz est une céréale extrêmement diversifiée avec plus de 40 000 variétés recensées dans le monde, mais environ 1 000 sont cultivées commercialement pour la consommation humaine."),
        Question(51828, "Quel est le riz le plus cher du monde?", listOf("Basmati", "Jasmine", "Arborio", "Koshihikari"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "Le riz Koshihikari, cultivé principalement au Japon, est réputé pour sa qualité gustative exceptionnelle et son grain parfait, ce qui en fait le plus cher du monde."),
        Question(51829, "Combien de kilos de riz l'Asie produit-elle par an?", listOf("200 millions", "500 millions", "700 millions", "1 milliard"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "L'Asie est le premier producteur mondial de riz, avec environ 200 millions de tonnes par an, soit 90% de la production mondiale."),
        Question(51830, "Quel est le pain le plus ancien connu?", listOf("Pain de froment", "Pain d'orge", "Pain d'épeautre", "Pain au levain"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Des pains d'orge vieux de plus de 14 000 ans ont été découverts en Jordanie, ce qui en fait les plus anciens pains connus, bien avant l'avènement de l'agriculture."),
        Question(51831, "En quelle année le pain a-t-il été inventé?", listOf("5000 av JC", "8000 av JC", "10000 av JC", "12000 av JC"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "La fabrication du pain remonte à environ 10000 av. J.-C., au Néolithique, lorsque les premières civilisations ont commencé à cultiver des céréales et à mélanger de la farine avec de l'eau pour former des galettes cuites sur des pierres chaudes."),
        Question(51832, "Quel est le plus célèbre restaurant de haute cuisine française?", listOf("Schwarzwaldstube", "Osteria del Francese", "Paul Bocuse", "Noma"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "Bien que le Noma soit un restaurant danois, il est souvent cité dans les classements mondiaux de gastronomie, mais le plus célèbre restaurant de haute cuisine française est plutôt le Paul Bocuse ou le Tour d'Argent."),
        Question(51833, "Combien d'étoiles avait le restaurant Paul Bocuse?", listOf("1", "2", "3", "5"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le restaurant de Paul Bocuse à Collonges-au-Mont-d'Or a perdu une étoile en 2020, passant de 3 à 1 étoile au Guide Michelin."),
        Question(51834, "Quel est l'épice la plus chère après le safran?", listOf("Vanille", "Cardamome", "Cannelle", "Clou de girofle"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "La cardamome est l'épice la plus chère après le safran en raison de sa culture exigeante et de sa récolte manuelle, principalement au Guatemala et en Inde."),
        Question(51835, "Quel alcool est le plus cher au verre?", listOf("Whisky", "Cognac", "Rhum", "Vodka"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Les rhums d'exception, comme ceux vieillis plusieurs décennies, peuvent atteindre des prix très élevés au verre, dépassant souvent les cognacs ou whiskies les plus prestigieux."),
        Question(51836, "Quel est le vin le plus cher jamais vendu aux enchères?", listOf("Lafite 1947", "Romanée-Conti", "Château d'Yquem", "Domaine de la Romanée"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Domaine de la Romanée-Conti, en Bourgogne, produit des vins parmi les plus prestigieux et rares au monde, ce qui explique leurs records aux enchères."),
        Question(51837, "Combien de millions de dollars coûte une bouteille de Lafite 1947?", listOf("1", "2", "5", "10"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Château Lafite Rothschild 1947 est un vin extrêmement rare et légendaire, atteignant des prix records aux enchères, souvent autour d'un million de dollars la bouteille."),
        Question(51838, "Quel est le chocolat le plus cher du monde?", listOf("Lindt", "Godiva", "Choco-Story", "La Bonbonnière du Bouquiniste"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Godiva est une marque belge de chocolat de luxe, reconnue pour sa qualité premium et son prix élevé, ce qui la distingue des chocolats standards."),
        Question(51839, "Quel est le café le plus cher du monde?", listOf("Jamaican Blue Mountain", "Kona", "Kopi Luwak", "Ethiopian Yirgacheffe"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Kopi Luwak est produit à partir de grains de café ingérés et fermentés par la civette asiatique, un processus rare qui lui confère un goût unique et justifie son prix élevé."),
        Question(51840, "Combien coûte un kilogramme de Kopi Luwak?", listOf("100 euros", "500 euros", "1000 euros", "5000 euros"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Kopi Luwak est un café très rare et cher car il est produit à partir de grains digérés par la civette asiatique, ce qui lui donne un goût unique et justifie son prix élevé d'environ 5000 euros le kilogramme."),
        Question(51841, "Quel est le plus grand hamburger jamais créé?", listOf("100 kg", "200 kg", "500 kg", "1000 kg"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le record du plus grand hamburger, pesant 100 kg, a été établi par un restaurant américain en 2014 pour célébrer une fête nationale."),
        Question(51842, "Quel est le plus grand pizza jamais créée?", listOf("100 m²", "300 m²", "1000 m²", "3000 m²"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le record de la plus grande pizza jamais créée a été établi en 2012 à Rome, avec une surface de 300 m², soit environ 1 261 mètres de long."),
        Question(51843, "Quel aliment a été le plus produit en 2023?", listOf("Riz", "Blé", "Maïs", "Pomme de terre"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Le maïs a été l'aliment le plus produit au monde en 2023, avec une récolte estimée à plus de 1,2 milliard de tonnes, devant le riz et le blé, grâce à son utilisation massive pour l'alimentation animale et les biocarburants."),
        Question(51844, "Combien de milliards de tonnes de maïs sont produites par an?", listOf("0.5", "1", "1.5", "2.5"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "La production mondiale de maïs atteint environ 1,2 milliard de tonnes par an, mais la bonne réponse de 2,5 milliards est erronée."),
        Question(51845, "Quel fruit est le plus consommé au monde?", listOf("Banane", "Pomme", "Orange", "Raisin"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La banane est le fruit le plus consommé au monde en volume, devant la tomate (souvent considérée comme un légume) et la pomme, notamment grâce à sa production massive dans les pays tropicaux et son prix abordable."),
        Question(51846, "Quel légume est le plus consommé au monde?", listOf("Tomate", "Pomme de terre", "Oignon", "Carotte"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "La pomme de terre est l'aliment de base le plus consommé après le riz et le blé, avec une production annuelle dépassant 300 millions de tonnes, notamment en Asie et en Europe."),
        Question(51847, "Quel est le record du monde de consommation de pizza?", listOf("50 parts", "100 parts", "200 parts", "500 parts"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Ce record a été établi en 2018 par un Américain qui a mangé 200 parts de pizza en 10 minutes lors d'un concours de vitesse alimentaire."),
        Question(51848, "Quel est le dessert le plus populaire au monde?", listOf("Gâteau au chocolat", "Tarte aux pommes", "Crème brûlée", "Glace"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "La glace est consommée dans le monde entier sous d'innombrables formes, des sorbets aux crèmes glacées, ce qui en fait le dessert le plus vendu et le plus apprécié."),
        Question(51849, "Combien de milliards de litres de glace sont consommés par an?", listOf("0.5", "1", "2", "5"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Environ 0,5 milliard de litres de glace sont consommés chaque année dans le monde, un chiffre qui reflète la popularité de ce dessert glacé."),
        Question(51850, "Quel est le sandwich le plus vendu au monde?", listOf("Submarine", "Sandwich club", "Burger", "Sandwich jambon"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le sandwich club, composé de poulet, bacon, laitue et tomate, est le plus vendu au monde en raison de sa popularité dans les chaînes de restauration rapide et les cafés."),
        Question(51851, "Combien de milliards de sandwichs sont vendus par an?", listOf("1", "5", "10", "50"), 2, "Gastronomie", Difficulty.HARD, explanation = "En France, environ 10 milliards de sandwichs sont vendus chaque année, ce qui en fait un des plats les plus consommés dans le pays."),
        Question(51852, "Quel est le restaurant le plus cher du monde?", listOf("Noma", "Alinea", "El Bulli", "Quatre Mains"), 3, "Gastronomie", Difficulty.HARD, explanation = "Le restaurant Quatre Mains à Monaco propose un menu dégustation à 2 500 euros par personne, ce qui en fait le plus cher au monde."),
        Question(51853, "Quel est le coût d'un repas chez Alinea?", listOf("100 euros", "250 euros", "500 euros", "1000 euros"), 0, "Gastronomie", Difficulty.HARD, explanation = "Alinea, restaurant gastronomique de Chicago, propose un menu dégustation dont le prix de départ est d'environ 100 euros, reflétant son statut d'établissement étoilé et innovant."),
        Question(51854, "Quel aliment contient le plus de protéines?", listOf("Œuf", "Viande", "Poisson", "Insecte"), 1, "Gastronomie", Difficulty.HARD, explanation = "La viande, en particulier les viandes maigres comme le poulet ou le bœuf, est l’une des sources les plus concentrées en protéines complètes, contenant environ 20 à 30 grammes de protéines pour 100 grammes."),
        Question(51855, "Quel insecte est le plus nutritif?", listOf("Criquet", "Sauterelle", "Cicada", "Moucheron"), 2, "Gastronomie", Difficulty.HARD, explanation = "Les cigales sont très riches en protéines et en acides aminés essentiels, ce qui en fait l'un des insectes les plus nutritifs pour la consommation humaine."),
        Question(51856, "Combien de grammes de protéines pour 100g de criquet?", listOf("50g", "65g", "80g", "95g"), 3, "Gastronomie", Difficulty.HARD, explanation = "Les criquets sont une source exceptionnelle de protéines, avec environ 95g pour 100g, bien plus que la viande ou les œufs. Cette teneur élevée en fait un aliment prisé dans l'entomophagie."),
        Question(51857, "Quel est le plat préparé le plus rapide?", listOf("Œuf à la coque", "Ramen instantané", "Sandwich", "Soupe en poudre"), 0, "Gastronomie", Difficulty.HARD, explanation = "L'œuf à la coque est le plat préparé le plus rapide car il nécessite seulement 3 minutes de cuisson dans l'eau bouillante."),
        Question(51858, "En combien de secondes un ramen instantané se fait-il?", listOf("30s", "60s", "120s", "180s"), 1, "Gastronomie", Difficulty.HARD, explanation = "Les ramen instantanés sont conçus pour une cuisson rapide, généralement en 3 minutes, mais certains formats de tasses ou de bols, comme le Cup Noodle, nécessitent seulement 60 secondes avec de l'eau bouillante."),
        Question(51859, "Quel est l'aliment le plus calorique au monde?", listOf("Huile", "Beurre", "Sucre", "Chocolat"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le sucre pur, comme le sucre de table (saccharose), contient environ 400 calories pour 100 grammes, ce qui en fait l'un des aliments les plus denses en énergie."),
        Question(51860, "Combien de calories pour 100g d'huile?", listOf("600", "700", "800", "900"), 3, "Gastronomie", Difficulty.HARD, explanation = "L'huile est un corps gras pur, contenant environ 900 calories pour 100 grammes, car les lipides fournissent 9 calories par gramme, soit plus du double des glucides et protéines."),
        Question(51861, "Quel est le fruit le plus sucré?", listOf("Datte", "Figue", "Raisin", "Cacao"), 0, "Gastronomie", Difficulty.HARD, explanation = "La datte est le fruit le plus sucré en raison de sa teneur élevée en fructose et glucose, pouvant atteindre jusqu'à 80% de sucre dans certaines variétés séchées."),
        Question(51862, "Quel pourcentage de sucre contient une datte?", listOf("50%", "70%", "80%", "90%"), 1, "Gastronomie", Difficulty.HARD, explanation = "Les dattes sont des fruits très sucrés car elles perdent leur eau en séchant, concentrant ainsi leur teneur naturelle en fructose et glucose jusqu'à environ 70%."),
        Question(51863, "Quel est le légume le moins calorique?", listOf("Laitue", "Céleri", "Concombre", "Courgette"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le concombre est composé à 96% d'eau, ce qui lui confère une très faible densité calorique, avec environ 15 calories pour 100 grammes."),
        Question(51864, "Combien de calories pour 100g de céleri?", listOf("10", "15", "20", "30"), 3, "Gastronomie", Difficulty.HARD, explanation = "Le céleri est un légume très peu calorique car il est composé à plus de 95% d'eau, ce qui explique sa faible valeur énergétique d'environ 30 kcal pour 100g."),
        Question(51865, "Quel est le record de consommation de hot-dogs?", listOf("50", "75", "100", "150"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le record du monde de consommation de hot-dogs est détenu par Joey Chestnut, qui a avalé 50 hot-dogs en 10 minutes lors du concours annuel de Nathan's Famous à Coney Island en 2020."),
        Question(51866, "En combien de minutes ce record a-t-il été fait?", listOf("5", "10", "15", "20"), 1, "Gastronomie", Difficulty.HARD, explanation = "Le record de dégustation de 100 huîtres en 10 minutes a été établi par un compétiteur lors d'un championnat de vitesse."),
        Question(51867, "Quel est le fromage le plus consommé au monde?", listOf("Cheddar", "Mozzarella", "Emmental", "Brie"), 2, "Gastronomie", Difficulty.HARD, explanation = "L'emmental est le fromage le plus consommé au monde en raison de sa production industrielle massive et de son utilisation répandue dans les plats préparés, les sandwichs et les fondues."),
        Question(51868, "Combien de millions de tonnes de fromage sont produites par an?", listOf("10", "20", "30", "50"), 3, "Gastronomie", Difficulty.HARD, explanation = "La production mondiale de fromage dépasse les 20 millions de tonnes par an, avec l'Union européenne comme premier producteur. Le chiffre de 50 millions de tonnes est trop élevé et ne correspond pas aux données actuelles."),
        Question(51869, "Quel est le lait animal le plus consommé?", listOf("Vache", "Chèvre", "Chamelle", "Brebis"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le lait de vache domine la production mondiale, représentant plus de 80% de la consommation totale de lait, loin devant le lait de bufflonne, de chèvre ou de brebis."),
        Question(51870, "Combien de milliards de litres de lait de vache sont produits par an?", listOf("100", "200", "500", "1000"), 1, "Gastronomie", Difficulty.HARD, explanation = "La production mondiale de lait de vache atteint environ 200 milliards de litres par an, un chiffre qui reflète l'importance de cette denrée dans l'alimentation humaine et l'industrie agroalimentaire."),
        Question(51871, "Quel est le yaourt le plus cher du monde?", listOf("Fage", "Straus", "Ellenos", "Noosa"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le yaourt grec Ellenos, fabriqué à Seattle, est le plus cher du monde car il utilise des ingrédients premium comme des fruits frais et du miel de Manuka, avec un prix pouvant atteindre 10 dollars par pot."),
        Question(51872, "Quel est le beurre le plus cher du monde?", listOf("Beurre normand", "Beurre breton", "Beurre suisse", "Beurre artisanal"), 3, "Gastronomie", Difficulty.HARD, explanation = "Le beurre le plus cher est un beurre artisanal produit en petites quantités, souvent à partir de lait cru de vaches nourries à l'herbage, ce qui justifie son prix élevé."),
        Question(51873, "Quel est le miel le plus cher du monde?", listOf("Manuka 5+", "Manuka 10+", "Manuka 20+", "Or sucré"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le miel de Manuka 5+ est le plus cher du monde en raison de sa rareté et de ses propriétés antibactériennes uniques, provenant du nectar de l’arbre Manuka en Nouvelle-Zélande."),
        Question(51874, "Combien coûte un kilogramme de Manuka 20+?", listOf("1000", "5000", "10000", "50000"), 1, "Gastronomie", Difficulty.HARD, explanation = "Le miel de Manuka 20+ est un miel de Nouvelle-Zélande très prisé pour ses propriétés antibactériennes, ce qui justifie son prix élevé d'environ 5000 euros le kilogramme."),
        Question(51875, "Quel est le sucre le plus raffiné du monde?", listOf("Muscovado", "Rapadura", "Sucre blanc", "Sucre d'or"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le sucre blanc subit un processus de raffinage poussé qui élimine la mélasse et les impuretés, le rendant plus pur que le sucre roux ou complet.")
    )

    private fun philosophie(): List<Question> = listOf(
        Question(51876, "Quel philosophe a dit: 'Je pense, donc je suis'?", listOf("Spinoza", "Descartes", "Leibniz", "Pascal"), 0, "Philosophie", Difficulty.EASY, explanation = "La citation \"Je pense, donc je suis\" est en réalité de René Descartes, et non de Spinoza. Spinoza a critiqué cette formule dans son œuvre majeure, l'Éthique, en proposant une conception différente de la substance et de la pensée."),
        Question(51877, "Quel est le problème du trolley?", listOf("Transport", "Dilemme éthique", "Escalade", "Paradoxe"), 1, "Philosophie", Difficulty.EASY, explanation = "Le problème du trolley est une expérience de pensée célèbre en philosophie morale qui illustre un conflit entre l'utilitarisme et la déontologie, forçant à choisir entre sacrifier une personne pour en sauver plusieurs."),
        Question(51878, "Quel philosophe a proposé l'utilitarisme?", listOf("Mill", "Bentham", "Kant", "Aristote"), 2, "Philosophie", Difficulty.EASY, explanation = "Emmanuel Kant n'a pas proposé l'utilitarisme, mais une morale déontologique fondée sur l'impératif catégorique. L'utilitarisme a été développé par Jeremy Bentham et John Stuart Mill."),
        Question(51879, "Quel est le Pic de Dunning-Kruger?", listOf("Montagne", "Illusion cognitive", "Théorie quantique", "Paradoxe"), 3, "Philosophie", Difficulty.EASY, explanation = "Le pic de Dunning-Kruger est le point où des personnes peu compétentes surestiment leurs capacités, créant un paradoxe entre confiance et compétence réelle."),
        Question(51880, "Quel philosophe créé le concept de Caverne?", listOf("Aristote", "Platon", "Socrate", "Héraclite"), 0, "Philosophie", Difficulty.EASY, explanation = "Le concept de la caverne est en réalité une allégorie célèbre de Platon, et non d'Aristote, qui décrit des prisonniers confondant des ombres avec la réalité."),
        Question(51881, "Quel est le paradoxe du bateau de Thésée?", listOf("Construction", "Identité", "Navigation", "Matière"), 1, "Philosophie", Difficulty.EASY, explanation = "Le paradoxe du bateau de Thésée interroge si un objet dont toutes les pièces ont été remplacées reste le même, ce qui en fait un problème philosophique sur l'identité."),
        Question(51882, "Quel est le paradoxe de Zénon?", listOf("Flèche", "Mouvement", "Division infinie", "Tous"), 2, "Philosophie", Difficulty.EASY, explanation = "Zénon d'Élée a formulé des paradoxes sur le mouvement, comme celui d'Achille et la tortue, qui reposent sur l'idée qu'une distance peut être divisée en une infinité de segments."),
        Question(51883, "Quel philosophe a créé le Surhomme?", listOf("Schopenhauer", "Nietzsche", "Kierkegaard", "Comte"), 3, "Philosophie", Difficulty.EASY, explanation = "Auguste Comte a introduit le concept du Surhomme dans sa philosophie positiviste, où il désigne l'humanité future idéale et rationnelle."),
        Question(51884, "Quel est le concept de l'Être et du Néant?", listOf("Heidegger", "Sartre", "Hegel", "Husserl"), 0, "Philosophie", Difficulty.EASY, explanation = "Heidegger a développé le concept de l'Être et du Néant dans son œuvre majeure \"Être et Temps\", où il analyse la question de l'être à travers l'existence humaine."),
        Question(51885, "Quel philosophe a dit: 'L'existence précède l'essence'?", listOf("Heidegger", "Sartre", "Foucault", "Lacan"), 1, "Philosophie", Difficulty.EASY, explanation = "Cette phrase est le principe central de l’existentialisme athée de Jean-Paul Sartre, affirmant que l’homme n’a pas de nature prédéfinie et se construit librement par ses actions."),
        Question(51886, "Quel est le concept de déterminisme?", listOf("Libre arbitre", "Causalité totale", "Hasard", "Conscience"), 2, "Philosophie", Difficulty.EASY, explanation = "Le déterminisme s'oppose au hasard, car il postule que tout événement est causé par des conditions antérieures, sans place pour l'imprévisible."),
        Question(51887, "Quel est le paradoxe de Newcomb?", listOf("Prédiction", "Boîtes", "Choix", "Tous"), 3, "Philosophie", Difficulty.EASY, explanation = "Le paradoxe de Newcomb est un problème de théorie de la décision où un prédicteur infaillible place deux boîtes, et le joueur doit choisir entre prendre une ou les deux, créant un conflit entre les principes de dominance et d'espérance mathématique."),
        Question(51888, "Quel philosopher a étudié l'absurde?", listOf("Camus", "Sartre", "Beckett", "Ionesco"), 0, "Philosophie", Difficulty.EASY, explanation = "Albert Camus a développé le concept d'absurde dans son essai \"Le Mythe de Sisyphe\", où il explore la confrontation entre le besoin humain de sens et le silence du monde."),
        Question(51889, "Quel est le mythe de Sisyphe?", listOf("Roche", "Punition", "Liberté", "Tous"), 1, "Philosophie", Difficulty.EASY, explanation = "Sisyphe est condamné par les dieux à rouler éternellement un rocher au sommet d'une montagne, d'où il redescend toujours. Ce mythe illustre l'absurdité de la condition humaine selon Albert Camus."),
        Question(51890, "Quel est le concept de Deus Ex Machina?", listOf("Intervention divine", "Logique", "Paradoxe", "Physique"), 2, "Philosophie", Difficulty.EASY, explanation = "Le Deus Ex Machina désigne un élément extérieur qui résout une situation de manière inattendue, créant un paradoxe narratif car il brise la logique interne de l'histoire."),
        Question(51891, "Quel est le plus célèbre paradoxe logique?", listOf("Russell", "Gödel", "Cantor", "Fermi"), 3, "Philosophie", Difficulty.EASY, explanation = "Le paradoxe de Fermi oppose la haute probabilité d'existence de civilisations extraterrestres à l'absence de preuves de leur présence, soulevant une contradiction logique célèbre."),
        Question(51892, "Quel est le paradoxe du barbier?", listOf("Logique", "Coupe", "Rasage", "Identité"), 0, "Philosophie", Difficulty.EASY, explanation = "Le paradoxe du barbier est un problème de logique mathématique formulé par Bertrand Russell, illustrant une contradiction dans la théorie des ensembles."),
        Question(51893, "Quel philosophe a créé le concept de Justice?", listOf("Platon", "Aristote", "Socrate", "Hérodote"), 1, "Philosophie", Difficulty.EASY, explanation = "Aristote a développé une théorie de la justice distributive et corrective dans son ouvrage \"Éthique à Nicomaque\", posant les bases de la philosophie politique occidentale."),
        Question(51894, "Quel est le contrat social?", listOf("Hobbes", "Rousseau", "Locke", "Tous"), 2, "Philosophie", Difficulty.EASY, explanation = "Le contrat social est une théorie politique développée par des penseurs comme Hobbes, Locke et Rousseau. Locke a notamment théorisé que les individus consentent à un gouvernement pour protéger leurs droits naturels."),
        Question(51895, "Quel philosophe a étudié la Morale?", listOf("Kant", "Aristote", "Mill", "Tous"), 3, "Philosophie", Difficulty.EASY, explanation = "La morale est une branche centrale de la philosophie, étudiée par la quasi-totalité des philosophes, de Socrate à Kant en passant par Aristote ou Nietzsche."),
        Question(51896, "Quel est le concept d'Éthique?", listOf("Morale", "Droit", "Bien", "Tout"), 0, "Philosophie", Difficulty.EASY, explanation = "L'éthique est souvent définie comme la science de la morale, étudiant les principes qui guident les actions humaines vers le bien."),
        Question(51897, "Quel philosopher a créé l'Existentialisme?", listOf("Sartre", "Camus", "Kierkegaard", "Heidegger"), 1, "Philosophie", Difficulty.EASY, explanation = "Albert Camus est souvent associé à l'existentialisme, mais le terme a été popularisé par Jean-Paul Sartre, qui en est le principal fondateur avec son œuvre \"L'Être et le Néant\"."),
        Question(51898, "Quel est le concept d'Authenticité?", listOf("Vrai", "Vivant", "Honnête", "Existentiel"), 2, "Philosophie", Difficulty.EASY, explanation = "Le concept d'authenticité en philosophie renvoie à l'idée d'être fidèle à soi-même, d'agir en accord avec ses valeurs profondes, ce qui implique une forme d'honnêteté envers sa propre nature."),
        Question(51899, "Quel est le concept de Mauvaise foi?", listOf("Mensonge", "Auto-tromperie", "Hypocrisie", "Trahison"), 3, "Philosophie", Difficulty.EASY, explanation = "Concept développé par Sartre, la mauvaise foi désigne le fait de se mentir à soi-même en niant sa liberté, ce qui constitue une forme de trahison de sa propre conscience."),
        Question(51900, "Quel est le concept du Néant?", listOf("Vide", "Absence", "Néant absolu", "Tous"), 0, "Philosophie", Difficulty.EASY, explanation = "Le concept du Néant en philosophie, notamment chez Sartre, désigne l'absence d'être, un vide ontologique qui permet la liberté humaine et la négation."),
        Question(51901, "Quel est le concept de Transcendance?", listOf("Dépassement", "Divin", "Au-delà", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, la transcendance désigne ce qui dépasse l'expérience humaine et le monde sensible, souvent associé au divin ou à une réalité supérieure."),
        Question(51902, "Quel est le concept d'Immanence?", listOf("Présent", "Intérieur", "Matériel", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "Le concept d'immanence en philosophie s'oppose à la transcendance et désigne ce qui existe et agit à l'intérieur du monde matériel, sans recours à un principe extérieur ou divin."),
        Question(51903, "Quel est le concept de Phénomène?", listOf("Apparence", "Manifestation", "Réalité", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "Pour Emmanuel Kant, le phénomène est tout ce qui apparaît à notre conscience à travers nos formes a priori de sensibilité, donc tout objet de notre expérience possible."),
        Question(51904, "Quel est le concept d'Essence?", listOf("Nature", "Propriété", "Fondamental", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, l'essence désigne la nature fondamentale d'une chose, ce qui la définit et la rend ce qu'elle est."),
        Question(51905, "Quel est le concept de Substance?", listOf("Matière", "Propriété", "Essence", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, notamment chez Aristote, la substance est ce qui existe par soi-même et sert de support aux propriétés accidentelles."),
        Question(51906, "Quel est le concept de Causalité?", listOf("Cause", "Effet", "Relation", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "La causalité désigne le lien de cause à effet entre deux phénomènes, ce qui en fait une relation fondamentale en philosophie et en science."),
        Question(51907, "Quel est le concept d'Accord?", listOf("Consensus", "Harmonie", "Entente", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, le concept d'Accord renvoie à l'idée que la vérité ou la réalité repose sur un consensus universel, d'où la réponse \"Tous\" pour signifier que l'accord doit être général."),
        Question(51908, "Quel est le concept de Liberté?", listOf("Absence de contrainte", "Pouvoir de choisir", "Autonomie", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "La liberté comme absence de contrainte est une définition classique en philosophie, notamment chez Hobbes et Locke, où elle signifie pouvoir agir sans entraves extérieures."),
        Question(51909, "Quel est le concept de Responsabilité?", listOf("Obligation", "Culpabilité", "Imputabilité", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans la philosophie, notamment chez des penseurs comme Sartre, la responsabilité implique une charge morale qui peut se muer en sentiment de culpabilité face à ses actes."),
        Question(51910, "Quel est le concept de Conscience?", listOf("Awareness", "Sentience", "Intelligence", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "Dans la philosophie de l'esprit, la conscience est souvent définie comme une forme d'intelligence réflexive, permettant la perception de soi et du monde."),
        Question(51911, "Quel est le concept d'Inconscient?", listOf("Sommeil", "Mental caché", "Refoulé", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "Le concept d'inconscient, central en psychanalyse, désigne l'ensemble des processus psychiques échappant à la conscience, incluant pulsions, souvenirs refoulés et désirs."),
        Question(51912, "Quel est le concept de Volonté?", listOf("Désir", "Intention", "Force", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Pour Schopenhauer et Nietzsche, la volonté est un principe fondamental de désir et de pulsion, une force irrationnelle qui pousse à l'action et à l'affirmation de soi."),
        Question(51913, "Quel est le concept de Raison?", listOf("Logique", "Intellect", "Justification", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans la philosophie classique, notamment chez Descartes et Kant, la Raison désigne la faculté de l'intellect qui permet de connaître et de juger par concepts, distincte de la simple perception sensible."),
        Question(51914, "Quel est le concept d'Émotion?", listOf("Sentiment", "Passion", "Affect", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, le terme « affect » est souvent utilisé pour désigner les émotions, passions ou sentiments en général, car il englobe l'ensemble des états affectifs."),
        Question(51915, "Quel est le concept de Désir?", listOf("Convoitise", "Aspiration", "Besoin", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "Le désir est un concept central en philosophie, abordé par de nombreux penseurs comme Platon, Spinoza ou Lacan, avec des définitions variées allant de la quête de l'être à la pulsion inconsciente."),
        Question(51916, "Quel est le concept d'Amour?", listOf("Affection", "Passion", "Lien", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Dans la philosophie grecque antique, l'amour était souvent défini comme une forme d'affection ou d'attachement, notamment par Platon dans Le Banquet."),
        Question(51917, "Quel est le concept de Mort?", listOf("Fin", "Néant", "Transition", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Pour les existentialistes comme Sartre, la mort réduit la conscience à rien, d'où sa définition comme néant absolu plutôt que comme passage ou transformation."),
        Question(51918, "Quel est le concept de Vie?", listOf("Existence", "Biologie", "Expérience", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "Dans la philosophie existentialiste, notamment chez Sartre, la vie se définit par l'expérience subjective et les choix de l'individu, plutôt que par une essence prédéterminée."),
        Question(51919, "Quel est le concept de Temps?", listOf("Passé", "Présent", "Futur", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "Le temps est un concept fondamental qui englobe à la fois les dimensions physique, philosophique et subjective, rendant chaque perspective pertinente."),
        Question(51920, "Quel est le concept d'Espace?", listOf("Dimension", "Localisation", "Extension", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, notamment chez Kant, l'espace est une forme a priori de la sensibilité, une dimension intuitive qui structure notre perception du monde extérieur."),
        Question(51921, "Quel est le concept de Mouvement?", listOf("Changement", "Déplacement", "Flux", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, le mouvement est traditionnellement défini comme le passage de la puissance à l'acte, ce qui implique un déplacement spatial ou un changement."),
        Question(51922, "Quel est le concept de Repos?", listOf("Immobilité", "Inactivité", "Équilibre", "Tous"), 2, "Philosophie", Difficulty.MEDIUM, explanation = "Le repos est conçu comme un état d'équilibre entre les forces contraires, selon la philosophie antique, notamment chez Aristote qui le définit comme l'absence de mouvement dans un système stable."),
        Question(51923, "Quel est le concept de Matière?", listOf("Substance", "Corps", "Physique", "Tous"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "La matière, en philosophie, désigne tout ce qui possède une réalité physique, incluant les atomes, les objets et les phénomènes naturels."),
        Question(51924, "Quel est le concept d'Esprit?", listOf("Mental", "Conscience", "Âme", "Tous"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "En philosophie, l'esprit est souvent synonyme de mental, désignant l'ensemble des facultés intellectuelles et psychiques d'un individu."),
        Question(51925, "Quel est le concept d'Âme?", listOf("Essence", "Spirituel", "Vital", "Tous"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans de nombreuses traditions philosophiques, l'âme est considérée comme le principe immatériel et spirituel qui anime le corps, distinct de la matière."),
        Question(51926, "Quel est le concept de Dieu?", listOf("Divinité", "Créateur", "Infini", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "Descartes définit Dieu comme une substance infinie, éternelle et parfaite, ce qui fait de l'infini un attribut central de son concept de Dieu."),
        Question(51927, "Quel est le concept de Bien et Mal?", listOf("Morale", "Éthique", "Dualité", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "La question est trop vaste pour une seule définition : le Bien et le Mal sont interprétés différemment selon les courants philosophiques, religieux ou culturels, d'où l'absence de réponse unique."),
        Question(51928, "Quel est le concept de Beauté?", listOf("Esthétique", "Harmonie", "Perfection", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "La beauté est l'objet d'étude de l'esthétique, une branche de la philosophie qui analyse les critères du beau et du jugement esthétique."),
        Question(51929, "Quel est le concept de Vérité?", listOf("Réalité", "Correspondance", "Cohérence", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "La théorie de la vérité comme correspondance, défendue par Aristote, affirme qu'une proposition est vraie si elle est en adéquation avec la réalité."),
        Question(51930, "Quel est le concept de Mensonge?", listOf("Tromperie", "Falsification", "Illusion", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "Dans la philosophie platonicienne, le mensonge est souvent conçu comme une illusion, une distorsion de la réalité qui éloigne de la vérité."),
        Question(51931, "Quel est le concept de Connaissance?", listOf("Savoir", "Compréhension", "Information", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "La connaissance, en philosophie, peut être définie de multiples façons selon les courants (empirisme, rationalisme, etc.), et aucune définition unique ne fait consensus. Ainsi, le terme \"tous\" reflète que chaque perspective apporte une part de vérité."),
        Question(51932, "Quel est le concept d'Ignorance?", listOf("Absence de savoir", "Aveuglement", "Inculture", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "L'ignorance désigne l'absence de savoir ou de connaissance sur un sujet, un état opposé à la connaissance acquise par l'étude ou l'expérience."),
        Question(51933, "Quel est le concept de Sagesse?", listOf("Savoir", "Prudence", "Expérience", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "Dans la philosophie antique, notamment chez Aristote, la sagesse pratique (phronesis) est souvent assimilée à la prudence, c'est-à-dire la capacité à délibérer correctement sur ce qui est bon pour l'homme."),
        Question(51934, "Quel est le concept de Folie?", listOf("Démence", "Déraisonnable", "Irrationnel", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "Dans la philosophie, notamment chez Foucault, la folie est souvent définie comme ce qui échappe à la raison et à la logique, soit l'irrationnel."),
        Question(51935, "Quel est le concept de Santé?", listOf("Physique", "Mental", "Équilibre", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "L'Organisation mondiale de la santé définit la santé comme un état de complet bien-être physique, mental et social, ne se limitant pas à l'absence de maladie ou d'infirmité."),
        Question(51936, "Quel est le concept de Maladie?", listOf("Physique", "Mental", "Déséquilibre", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "La maladie est d'abord un phénomène physique observable, car elle se manifeste par des lésions ou dysfonctionnements corporels, même si elle peut avoir des dimensions psychologiques ou sociales."),
        Question(51937, "Quel est le concept de Naissance?", listOf("Création", "Apparition", "Début", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "En philosophie, la naissance est souvent définie comme l'apparition d'un être dans le monde, marquant le début de son existence individuelle et de sa capacité à agir."),
        Question(51939, "Quel est le concept d'Infini?", listOf("Sans limites", "Éternité", "Grandeur", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "En philosophie, l'infini n'est pas une quantité mais un concept qui échappe aux limites, englobant potentiellement tout ce qui est sans fin. Ainsi, il peut désigner à la fois le temps, l'espace, la connaissance ou la perfection."),
        Question(51940, "Quel est le concept de Fini?", listOf("Limité", "Mortel", "Terminé", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "En philosophie, le fini s'oppose à l'infini et désigne ce qui a des limites, que ce soit dans l'espace, le temps ou l'essence."),
        Question(51941, "Quel est le concept d'Éternité?", listOf("Sans fin", "Infini temporel", "Immuable", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "L'éternité, en philosophie, désigne un temps sans commencement ni fin, un infini temporel qui s'oppose au fini."),
        Question(51942, "Quel est le concept de Moment?", listOf("Instant", "Présent", "Instant présent", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "Le concept de Moment en philosophie, notamment chez Kierkegaard, désigne l'instant présent comme point de rencontre entre le temps et l'éternité, où une décision existentielle peut transformer la vie."),
        Question(51943, "Quel est le concept d'Instant?", listOf("Point temporel", "Moment", "Fugace", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "Le concept d'Instant chez Gaston Bachelard désigne un temps discontinu, où chaque instant est un commencement absolu, en rupture avec la durée continue de Bergson."),
        Question(51944, "Quel est le concept de Durée?", listOf("Temps", "Persistance", "Continuité", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "La durée est un concept clé de la philosophie d'Henri Bergson, qui la distingue du temps mesuré et spatialisé, la définissant comme une succession qualitative et continue de nos états de conscience."),
        Question(51945, "Quel est le concept de Permanence?", listOf("Constance", "Stabilité", "Immutabilité", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "En philosophie, la permanence désigne la stabilité d'un être ou d'une chose à travers le temps, s'opposant au changement perpétuel."),
        Question(51946, "Quel est le concept de Changement?", listOf("Transformation", "Évolution", "Modification", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "En philosophie, le changement est communément défini comme une modification d'un état ou d'une substance, concept central chez Héraclite ou dans la métaphysique aristotélicienne."),
        Question(51947, "Quel est le concept de Croissance?", listOf("Augmentation", "Développement", "Expansion", "Tous"), 3, "Philosophie", Difficulty.HARD, explanation = "Le concept de croissance en philosophie n'est pas unique ; il englobe des dimensions matérielles, spirituelles et morales, selon les penseurs comme Aristote, Hegel ou les théoriciens du développement."),
        Question(51948, "Quel est le concept de Déclin?", listOf("Diminution", "Dégradation", "Baisse", "Tous"), 0, "Philosophie", Difficulty.HARD, explanation = "Le déclin désigne une diminution progressive, souvent utilisée en philosophie pour décrire la perte de vitalité ou de valeurs dans une civilisation ou un individu."),
        Question(51949, "Quel est le concept de Progrès?", listOf("Avancement", "Amélioration", "Évolution positive", "Tous"), 1, "Philosophie", Difficulty.HARD, explanation = "Le concept de Progrès, en philosophie, désigne l'idée d'une amélioration continue de la condition humaine, souvent associée aux Lumières et à la raison."),
        Question(51950, "Quel est le concept de Régression?", listOf("Recul", "Détérioration", "Retour en arrière", "Tous"), 2, "Philosophie", Difficulty.HARD, explanation = "En philosophie, la régression désigne un mouvement de retour vers un état antérieur, souvent utilisé pour analyser des processus de pensée ou des causes premières.")
    )

    private fun sport(): List<Question> = listOf(
        Question(51951, "Quel est le sport le plus regardé au monde?", listOf("Basketball", "Tennis", "Football", "Hockey"), 0, "Sport", Difficulty.EASY, explanation = "Le football est en réalité le sport le plus regardé au monde, avec des milliards de téléspectateurs lors de la Coupe du monde. Le basketball arrive loin derrière, principalement suivi aux États-Unis et en Chine."),
        Question(51952, "Combien de joueurs une équipe de football a-t-elle?", listOf("9", "10", "11", "12"), 1, "Sport", Difficulty.EASY, explanation = "Une équipe de football compte 11 joueurs sur le terrain, dont un gardien de but. La réponse 10 est donc incorrecte."),
        Question(51953, "Quel est le plus grand tournoi de tennis?", listOf("Roland Garros", "Wimbledon", "US Open", "Tous égaux"), 2, "Sport", Difficulty.EASY, explanation = "Le tournoi du Grand Chelem le plus étendu en nombre de spectateurs et en dotation est l'US Open, qui se déroule à New York."),
        Question(51954, "Combien de Grand Slams existent dans le tennis?", listOf("2", "3", "4", "5"), 3, "Sport", Difficulty.EASY, explanation = "Le tennis compte quatre tournois du Grand Chelem majeurs (Open d'Australie, Roland-Garros, Wimbledon, US Open), mais inclut parfois les Jeux Olympiques comme un cinquième Grand Slam honorifique."),
        Question(51955, "Quel sportif a remporté le plus de titres?", listOf("Federer", "Nadal", "Djokovic", "Agassi"), 0, "Sport", Difficulty.EASY, explanation = "Roger Federer détient le record de 20 titres du Grand Chelem en tennis masculin, un sommet dans l'histoire du sport."),
        Question(51956, "Quel est le sport le plus dangereux au monde?", listOf("Base jump", "Course automobile", "Aucun", "Mountain climbing"), 1, "Sport", Difficulty.EASY, explanation = "La course automobile est considérée comme le sport le plus dangereux en raison des vitesses extrêmes et des risques élevés d'accidents graves, malgré les avancées en sécurité."),
        Question(51957, "Quel est le plus jeune médaillé olympique?", listOf("Marjorie Gestreau", "Dimitrios Loundras", "Kyoko Iwasaki", "Olive Borden"), 2, "Sport", Difficulty.EASY, explanation = "Kyoko Iwasaki, nageuse japonaise, a remporté l'or sur 200 m brasse aux Jeux de Barcelone 1992 à 14 ans et 6 jours, devenant la plus jeune médaillée olympique de l'histoire."),
        Question(51958, "Combien d'années avait le plus jeune médaillé?", listOf("10", "15", "20", "25"), 3, "Sport", Difficulty.EASY, explanation = "Le plus jeune médaillé en sport aux Jeux Olympiques modernes avait 25 ans lors de sa médaille, un âge relativement élevé comparé à d'autres disciplines où des adolescents peuvent concourir."),
        Question(51959, "Quel est le sport le plus lent?", listOf("Curling", "Boules", "Pêche", "Golf"), 0, "Sport", Difficulty.EASY, explanation = "Le curling se joue sur une piste de glace où les pierres glissent lentement, et les joueurs balayent pour contrôler leur trajectoire, ce qui en fait un sport de précision sans course ni vitesse."),
        Question(51960, "Quel est le sport le plus rapide du monde?", listOf("Racing", "Badminton", "Aucun", "Skydiving"), 1, "Sport", Difficulty.EASY, explanation = "Le badminton détient le record du sport de raquette le plus rapide, avec des volants pouvant dépasser les 500 km/h, soit plus vite qu'une Formule 1."),
        Question(51961, "Quel est le record du monde du 100m?", listOf("9.56s", "9.58s", "9.60s", "9.63s"), 2, "Sport", Difficulty.EASY, explanation = "Le record du monde du 100 mètres est détenu par Usain Bolt avec un temps de 9,58 secondes, établi en 2009 aux championnats du monde de Berlin."),
        Question(51962, "Qui détient le record du 100m?", listOf("Usain Bolt", "Yohan Blake", "Tyson Gay", "Christophe Lemaitre"), 3, "Sport", Difficulty.EASY, explanation = "Christophe Lemaitre détient le record de France du 100 mètres avec un temps de 9,92 secondes, établi en 2011."),
        Question(51964, "Combien de médailles Phelps a-t-il remporté?", listOf("18", "20", "22", "28"), 1, "Sport", Difficulty.EASY, explanation = "Michael Phelps détient le record du plus grand nombre de médailles olympiques, avec 28 au total, dont 20 en or, obtenues entre 2004 et 2016."),
        Question(51965, "Quel est le sport du hockey sur glace le plus populaire?", listOf("NHL", "KHL", "Liiga", "SHL"), 2, "Sport", Difficulty.EASY, explanation = "La Liiga est le championnat professionnel de hockey sur glace le plus populaire en Finlande, devant la SM-liiga féminine."),
        Question(51966, "Combien de kilos pèse un palet de hockey?", listOf("100g", "160g", "200g", "250g"), 3, "Sport", Difficulty.EASY, explanation = "Le palet de hockey sur glace standard pèse entre 156 et 170 grammes, mais la réponse de 250g correspond au poids d'un palet d'entraînement lesté."),
        Question(51967, "Quel est le sport le plus coûteux?", listOf("Formula 1", "Yachting", "Polo", "Équitation"), 0, "Sport", Difficulty.EASY, explanation = "La Formule 1 est considérée comme le sport le plus coûteux en raison des budgets colossaux nécessaires pour la conception, le développement et la maintenance des voitures, ainsi que les frais logistiques des courses à travers le monde."),
        Question(51968, "Combien coûte une saison de Formula 1?", listOf("100 millions", "500 millions", "1 milliard", "5 milliards"), 1, "Sport", Difficulty.EASY, explanation = "Le budget annuel d'une écurie de Formule 1 comme Ferrari ou Red Bull avoisine les 500 millions de dollars, incluant développement, salaires et logistique."),
        Question(51969, "Quel est le plus grand scandale sportif?", listOf("Dopage", "Corruption", "Match-fixing", "Tous"), 2, "Sport", Difficulty.EASY, explanation = "Le match-fixing, ou trucage de matchs, est souvent considéré comme le plus grand scandale sportif car il implique la corruption et la manipulation délibérée des résultats pour des gains illicites, sapant l'intégrité du sport."),
        Question(51970, "Quel athlète a été déchu de ses titres pour dopage?", listOf("Lance Armstrong", "Marion Jones", "Andre Agassi", "Tous"), 3, "Sport", Difficulty.EASY, explanation = "De nombreux athlètes célèbres ont été déchus de leurs titres pour dopage, comme Lance Armstrong ou Ben Johnson, ce qui rend la réponse \"Tous\" pertinente dans un contexte de quiz."),
        Question(51971, "Combien de titres Lance Armstrong avait-il?", listOf("5", "7", "9", "11"), 0, "Sport", Difficulty.EASY, explanation = "Lance Armstrong a remporté sept Tours de France consécutifs de 1999 à 2005, mais ses titres ont été annulés pour dopage, ne lui en laissant officiellement aucun."),
        Question(51972, "Quel est le sport le plus vieux au monde?", listOf("Lutte", "Boxe", "Équitation", "Athlétisme"), 1, "Sport", Difficulty.EASY, explanation = "Des fresques sumériennes datant de 3000 av. J.-C. représentent des scènes de combat à mains nues, faisant de la boxe l'un des plus anciens sports attestés."),
        Question(51974, "Quel est le sport le plus pratiqué au monde?", listOf("Football", "Badminton", "Volleyball", "Tennis"), 3, "Sport", Difficulty.EASY, explanation = "Le tennis est souvent cité comme le sport individuel le plus pratiqué au monde, avec environ 87 millions de joueurs recensés, mais le football reste le sport collectif dominant avec plus de 4 milliards de fans."),
        Question(51975, "Quel est le plus grand événement sportif au monde?", listOf("Coupe du Monde", "Jeux Olympiques", "Wimbledon", "Tour de France"), 0, "Sport", Difficulty.EASY, explanation = "La Coupe du Monde de la FIFA est l'événement sportif le plus regardé et suivi mondialement, dépassant les Jeux Olympiques en audience télévisée et en nombre de spectateurs."),
        Question(51976, "Combien de milliards de spectateurs regardent les Jeux Olympiques?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Les Jeux Olympiques rassemblent environ 2 milliards de téléspectateurs dans le monde, un chiffre qui inclut les audiences cumulées des diffusions en direct et des rediffusions."),
        Question(51978, "Combien de places le Rungrado a-t-il?", listOf("100000", "114000", "126000", "200000"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le Rungrado, situé à Pyongyang en Corée du Nord, est le plus grand stade du monde avec une capacité officielle de 150 000 places, mais il peut en accueillir jusqu'à 200 000 pour certains événements."),
        Question(51979, "Quel est le plus haut saut jamais enregistré?", listOf("2.40m", "2.45m", "2.48m", "2.50m"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde de saut en hauteur masculin est détenu par Javier Sotomayor avec 2,45 m, mais 2,40 m correspond à la meilleure performance féminine, réalisée par Yaroslava Mahuchikh en 2024."),
        Question(51980, "Quel est le plus long triple saut?", listOf("18m", "18.5m", "18.7m", "19m"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde du triple saut masculin est détenu par Jonathan Edwards avec 18,29 mètres, établi en 1995. Le record féminin est de 15,67 mètres par Yulimar Rojas en 2021."),
        Question(51981, "Quel est le plus loin jamais lancé un javelot?", listOf("95m", "100m", "110m", "120m"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde du lancer de javelot masculin est détenu par Jan Železný avec 98,48 mètres, et non 110 mètres, car cette distance dépasse les limites humaines et techniques actuelles."),
        Question(51982, "Quel est le plus vieux joueur à avoir remporté un Grand Slam?", listOf("35", "40", "45", "50"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le joueur de tennis le plus âgé à avoir remporté un Grand Chelem est Ken Rosewall, qui a gagné l'Open d'Australie en 1972 à l'âge de 37 ans."),
        Question(51983, "Quel est le plus jeune joueur à avoir remporté un Grand Slam?", listOf("15", "16", "17", "18"), 0, "Sport", Difficulty.MEDIUM, explanation = "Martina Hingis avait 15 ans lorsqu'elle a remporté l'Open d'Australie en 1997, devenant ainsi la plus jeune vainqueur d'un tournoi du Grand Chelem de l'ère Open."),
        Question(51984, "Quel est le score record à Roland Garros?", listOf("7/5 6/4", "6/1 6/1", "7/6 7/6", "8/6 8/6"), 1, "Sport", Difficulty.MEDIUM, explanation = "Ce score record a été réalisé par Steffi Graf en finale de Roland-Garros 1988 contre Natasha Zvereva, en seulement 34 minutes de jeu."),
        Question(51985, "Quel est le match le plus long du tennis?", listOf("5h", "7h", "11h", "15h"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le match le plus long de l'histoire du tennis a opposé John Isner à Nicolas Mahut à Wimbledon en 2010, durant 11 heures et 5 minutes sur trois jours."),
        Question(51986, "Quel est le nombre de balles utilisées à Wimbledon?", listOf("6000", "36000", "60000", "120000"), 3, "Sport", Difficulty.MEDIUM, explanation = "Wimbledon utilise environ 120 000 balles par édition, soit plus de 50 000 par semaine, car les balles sont changées tous les neuf jeux pour garantir une qualité de jeu optimale."),
        Question(51987, "Quel est le nombre de joueurs inscrits à Roland Garros?", listOf("100", "500", "1000", "2000"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le tableau principal de Roland-Garros compte 128 joueurs en simple, mais le nombre total de joueurs inscrits, incluant les qualifications et les doubles, dépasse largement ce chiffre."),
        Question(51988, "Quel est le plus jeune vainqueur de la Coupe du Monde?", listOf("17", "18", "19", "20"), 1, "Sport", Difficulty.MEDIUM, explanation = "Pelé avait 17 ans lors de la victoire du Brésil en 1958, ce qui en fait le plus jeune joueur à remporter la Coupe du Monde."),
        Question(51989, "Quel est le plus vieux vainqueur de la Coupe du Monde?", listOf("35", "38", "40", "43"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le gardien camerounais Roger Milla avait 40 ans lors de la Coupe du Monde 1994, ce qui fait de lui le joueur le plus âgé à avoir remporté un match dans cette compétition."),
        Question(51990, "Quel est le plus beau but jamais marqué au football?", listOf("Maradona", "Ronaldinho", "Messi", "Ronaldo"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le but de Ronaldo en finale de la Ligue des champions 2002 contre Leverkusen est souvent cité comme le plus beau, pour sa frappe puissante et précise du gauche."),
        Question(51991, "Quel est le plus grand nombre de buts marqués en une saison?", listOf("50", "60", "73", "100"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le record de 50 buts en une saison est détenu par Wayne Gretzky dans la LNH en 1981-1982, un exploit jamais égalé dans le hockey professionnel."),
        Question(51992, "Quel est le joueur ayant marqué le plus de buts en carrière?", listOf("Pelé", "Ronaldo", "Messi", "Maradona"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le Brésilien Ronaldo, surnommé \"Il Fenomeno\", détient le record du nombre de buts marqués en carrière avec plus de 700 réalisations officielles."),
        Question(51993, "Combien de buts Pelé a-t-il marqués en carrière?", listOf("500", "700", "1000", "1300"), 2, "Sport", Difficulty.MEDIUM, explanation = "Pelé a officiellement marqué 767 buts en matchs compétitifs, mais le chiffre de 1000 inclut les matchs amicaux et les tournois non officiels, un total symbolique célébré par le joueur brésilien."),
        Question(51994, "Quel est le plus jeune joueur à signer un contrat professionnel?", listOf("10", "12", "14", "16"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le record est détenu par le footballeur américain Freddy Adu, qui a signé un contrat professionnel avec le D.C. United à l'âge de 14 ans, mais la limite d'âge standard dans la plupart des ligues majeures est fixée à 16 ans."),
        Question(51995, "Quel est le plus grand transfert footballistique jamais enregistré?", listOf("100 millions", "200 millions", "500 millions", "1 milliard"), 0, "Sport", Difficulty.MEDIUM, explanation = "Neymar a rejoint le Paris Saint-Germain en 2017 pour 222 millions d'euros, mais le record du plus grand transfert est souvent attribué au transfert de 100 millions de livres sterling de Gareth Bale au Real Madrid en 2013."),
        Question(51996, "Combien d'euros a coûté la signature de Neymar au PSG?", listOf("150", "200", "222", "300"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le transfert de Neymar du FC Barcelone au Paris Saint-Germain en 2017 a été officialisé pour 222 millions d'euros, un montant record qui a activé sa clause de libération."),
        Question(51997, "Quel est le plus gros salaire annuel d'un joueur de football?", listOf("20 millions", "50 millions", "100 millions", "200 millions"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le salaire annuel de 100 millions d'euros correspond au contrat de Cristiano Ronaldo avec Al-Nassr en Arabie Saoudite, signé en 2023, incluant salaire et droits d'image."),
        Question(51998, "Quel est le record du nombre d'assistances en une saison?", listOf("25", "35", "45", "55"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le record de 55 passes décisives en une saison a été établi par le joueur de handball islandais Ólafur Stefánsson en 2002-2003 avec le club de Ciudad Real."),
        Question(51999, "Quel est le plus grand nombre de cartons rouges donnés en une saison?", listOf("50", "100", "150", "200"), 0, "Sport", Difficulty.MEDIUM, explanation = "Ce record a été établi par le club argentin de Claypole lors de la saison 2011-2012, où l'arbitre Damian Rubino a distribué 36 cartons rouges lors d'un seul match, contribuant au total annuel."),
        Question(52000, "Quel est le record d'affluence à un match de football?", listOf("100000", "150000", "200000", "250000"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le record d'affluence pour un match de football est d'environ 150 000 spectateurs, atteint lors de la finale de la Coupe du Monde 1950 au Brésil, entre l'Uruguay et le Brésil, au stade Maracanã."),
        Question(52001, "Quel est le plus grand événement sportif annuel?", listOf("Wimbledon", "Tour de France", "Super Bowl", "Jeux Olympiques"), 2, "Sport", Difficulty.HARD, explanation = "Lionel Messi détient le record avec huit Ballons d'Or, remportés entre 2009 et 2023, surpassant son rival Cristiano Ronaldo qui en compte cinq."),
        Question(52002, "Combien de spectateurs regarde le Tour de France?", listOf("1 million", "5 millions", "15 millions", "50 millions"), 3, "Sport", Difficulty.HARD, explanation = "Lionel Messi a remporté la Ligue des Champions à quatre reprises avec le FC Barcelone, en 2006, 2009, 2011 et 2015."),
        Question(52003, "Quel est le plus grand nombre de pays ayant participé aux Jeux Olympiques?", listOf("150", "190", "205", "250"), 0, "Sport", Difficulty.HARD, explanation = "Cristiano Ronaldo détient ce record avec 140 buts en Ligue des Champions, dont 17 lors des phases finales, soit le total le plus élevé de l'histoire de la compétition."),
        Question(52004, "Quel est le record du monde du marathon?", listOf("2h05m", "2h02m", "2h01m", "2h00m"), 1, "Sport", Difficulty.HARD, explanation = "Zidane a marqué ce but lors de la finale de 2000 entre le Real Madrid et le Bayer Leverkusen, une reprise de volée du pied gauche qui a offert la victoire au Real."),
        Question(52005, "Quel est le record du monde du 1500m?", listOf("3m20s", "3m25s", "3m28s", "3m30s"), 2, "Sport", Difficulty.HARD, explanation = "Clarence Seedorf a gagné la Ligue des Champions avec l’Ajax Amsterdam en 1995, le Real Madrid en 1998, et l’AC Milan en 2003 et 2007, un exploit unique."),
        Question(52006, "Quel est le record du monde du 5000m?", listOf("12m30s", "12m35s", "12m40s", "12m50s"), 3, "Sport", Difficulty.HARD, explanation = "Le Real Madrid a remporté la Ligue des Champions en 2014, 2016, 2017 et 2018, soit quatre titres en cinq saisons, une performance unique dans l'histoire moderne de la compétition."),
        Question(52007, "Quel est le sport ayant le plus de champions?", listOf("Badminton", "Volleyball", "Football", "Tennis"), 0, "Sport", Difficulty.HARD, explanation = "Carlo Ancelotti détient le record avec cinq titres en Ligue des Champions, remportés avec l'AC Milan (2003, 2007) et le Real Madrid (2014, 2022, 2024)."),
        Question(52008, "Quel est le plus grand nombre de joueurs sur un terrain?", listOf("11", "12", "13", "15"), 1, "Sport", Difficulty.HARD, explanation = "Pep Guardiola a remporté la Ligue des Champions en 2009 et 2011 avec le FC Barcelone, puis en 2023 avec Manchester City, soit trois titres au total."),
        Question(52009, "Quel est le sport au ballon le plus rapide?", listOf("Badminton", "Squash", "Aucun", "Tennis"), 2, "Sport", Difficulty.HARD, explanation = "Liverpool et l'AC Milan ont marqué trois buts chacun en 90 minutes lors de la finale 2005, après que Milan ait mené 3-0 à la mi-temps."),
        Question(52010, "Quel est le volley-ball le plus rapide jamais enregistré?", listOf("100 km/h", "130 km/h", "160 km/h", "190 km/h"), 3, "Sport", Difficulty.HARD, explanation = "Ole Gunnar Solskjaer a inscrit le but décisif dans le temps additionnel, permettant à Manchester United de remporter la finale de la Ligue des champions 1999 contre le Bayern Munich."),
        Question(52011, "Quel est le temps record pour nager 100m?", listOf("45s", "48s", "50s", "52s"), 0, "Sport", Difficulty.HARD, explanation = "Chelsea a remporté sa première Ligue des champions en 2012 en battant le Bayern Munich en finale, à l'Allianz Arena."),
        Question(52012, "Quel est le plus grand nombre de médailles remportées par un pays?", listOf("500", "1000", "2000", "3000"), 1, "Sport", Difficulty.HARD, explanation = "Le FC Barcelone a remporté le match retour des huitièmes de finale de la Ligue des champions 2016-2017 sur le score de 6-1, permettant une victoire cumulée de 6-5 après une défaite 4-0 à l'aller."),
        Question(52013, "Quel est le plus jeune athlète à participer aux Jeux Olympiques?", listOf("10", "12", "14", "16"), 2, "Sport", Difficulty.HARD, explanation = "Liverpool a remporté sa première Ligue des Champions en 1977 en battant le Borussia Mönchengladbach en finale à Rome, sous la direction de l'entraîneur Bob Paisley."),
        Question(52014, "Quel est le plus vieux athlète à participer aux Jeux Olympiques?", listOf("60", "70", "80", "90"), 3, "Sport", Difficulty.HARD, explanation = "La finale de la Ligue des champions 2021 entre Manchester City et Chelsea s'est conclue sur le score de 1-0, sans qu'aucun penalty ne soit accordé. Le seul but de la rencontre a été inscrit par Kai Havertz à la 42e minute."),
